internal void
lnk_init_error_handler(void)
{
  for (int i = LNK_Error_StopFirst; i < LNK_Error_StopLast; ++i) {
    g_error_mode_arr[i] = LNK_ErrorMode_Stop;
  }
  for (int i = LNK_Error_First; i < LNK_Error_Last; ++i) {
   g_error_mode_arr[i] = LNK_ErrorMode_Continue;
  }
  for (int i = LNK_Warning_First; i < LNK_Warning_Last; ++i) {
    g_error_mode_arr[i] = LNK_ErrorMode_Warn;
  }
}

internal String8
lnk_string_from_error_mode(LNK_ErrorMode mode)
{
  switch (mode) {
  case LNK_ErrorMode_Ignore:   return str8_lit("Ignore");
  case LNK_ErrorMode_Continue: return str8_lit("Error");
  case LNK_ErrorMode_Stop:     return str8_lit("Error");
  case LNK_ErrorMode_Warn:     return str8_lit("Warning");
  }
  return str8_zero();
}

internal void
lnk_errorfv(LNK_ErrorCode code, char *fmt, va_list args)
{
  if (g_error_mode_arr[code] == LNK_ErrorMode_Ignore) {
    return;
  }
  if (lnk_is_error_code_ignored(code)) {
    return;
  }

  Temp scratch = scratch_begin(0,0);
  String8 message = push_str8fv(scratch.arena, fmt, args);
  String8 string = push_str8f(scratch.arena, "%S(%03d): %S\n", lnk_string_from_error_mode(g_error_mode_arr[code]), code, message);
  fprintf(stderr, "%.*s", str8_varg(string));
  scratch_end(scratch);

  if (g_error_mode_arr[code] == LNK_ErrorMode_Stop) {
    lnk_exit(code);
  }
}

internal void
lnk_error(LNK_ErrorCode code, char *fmt, ...)
{
  va_list args;
  va_start(args, fmt);
  lnk_errorfv(code, fmt, args);
  va_end(args);
}

internal void
lnk_error_with_loc_fv(LNK_ErrorCode code, String8 obj_path, String8 lib_path, char *fmt, va_list args)
{
  Temp scratch = scratch_begin(0, 0);
  String8 text = push_str8fv(scratch.arena, fmt, args);
  if (obj_path.size) {
    if (lib_path.size) {
      lnk_error(code, "%S(%S): %S", lib_path, str8_skip_last_slash(obj_path), text);
    } else {
      lnk_error(code, "%S: %S", obj_path, text);
    }
  } else {
    lnk_error(code, "RADLINK: %S", text);
  }
  scratch_end(scratch);
}

internal void
lnk_error_with_loc(LNK_ErrorCode code, String8 obj_path, String8 lib_path, char *fmt, ...)
{
  va_list args; va_start(args, fmt);
  lnk_error_with_loc_fv(code, obj_path, lib_path, fmt, args);
  va_end(args);
}

void pstrcpy(char *buf, int buf_size, const char *str)
{
    int c;
    char *q = buf;

    if (buf_size <= 0)
        return;

    for(;;) {
        c = *str++;
        if (c == 0 || q >= buf + buf_size - 1)
            break;
        *q++ = c;
    }
    *q = '\0';
}

char *pstrcat(char *buf, int buf_size, const char *s)
{
    int len;
    len = strlen(buf);
    if (len < buf_size)
        pstrcpy(buf + len, buf_size - len, s);
    return buf;
}

int strstart(const char *str, const char *val, const char **ptr)
{
    const char *p, *q;
    p = str;
    q = val;
    while (*q != '\0') {
        if (*p != *q)
            return 0;
        p++;
        q++;
    }
    if (ptr)
        *ptr = p;
    return 1;
}

int has_suffix(const char *str, const char *suffix)
{
    size_t len = strlen(str);
    size_t slen = strlen(suffix);
    return (len >= slen && !memcmp(str + len - slen, suffix, slen));
}

size_t __unicode_to_utf8(uint8_t *buf, unsigned int c)
{
    uint8_t *q = buf;

    if (c < 0x800) {
        *q++ = (c >> 6) | 0xc0;
    } else {
        if (c < 0x10000) {
            *q++ = (c >> 12) | 0xe0;
        } else {
            if (c < 0x00200000) {
                *q++ = (c >> 18) | 0xf0;
            } else {
                return 0;
            }
            *q++ = ((c >> 12) & 0x3f) | 0x80;
        }
        *q++ = ((c >> 6) & 0x3f) | 0x80;
    }
    *q++ = (c & 0x3f) | 0x80;
    return q - buf;
}

int __unicode_from_utf8(const uint8_t *p, size_t max_len, size_t *plen)
{
    size_t len = 1;
    int c;

    c = p[0];
    if (c < 0xc0) {
        goto fail;
    } else if (c < 0xe0) {
        if (unlikely(max_len < 2 || (p[1] & 0xc0) != 0x80))
            goto fail;
        c = ((p[0] & 0x1f) << 6) | (p[1] & 0x3f);
        len = 2;
        if (unlikely(c < 0x80))
            goto fail;
    } else if (c < 0xf0) {
        if (unlikely(max_len < 2 || (p[1] & 0xc0) != 0x80))
            goto fail;
        if (unlikely(max_len < 3 || (p[2] & 0xc0) != 0x80)) {
            len = 2;
            goto fail;
        }
        c = ((p[0] & 0x0f) << 12) | ((p[1] & 0x3f) << 6) | (p[2] & 0x3f);
        len = 3;
        if (unlikely(c < 0x800))
            goto fail;
    } else if (c < 0xf8) {
        if (unlikely(max_len < 2 || (p[1] & 0xc0) != 0x80))
            goto fail;
        if (unlikely(max_len < 3 || (p[2] & 0xc0) != 0x80)) {
            len = 2;
            goto fail;
        }
        if (unlikely(max_len < 4 || (p[3] & 0xc0) != 0x80)) {
            len = 3;
            goto fail;
        }
        c = ((p[0] & 0x07) << 18) | ((p[1] & 0x3f) << 12) | ((p[2] & 0x3f) << 6) | (p[3] & 0x3f);
        len = 4;
        /* We explicitly accept surrogate pairs */
        if (unlikely(c < 0x10000 || c > 0x10ffff))
            goto fail;
    } else {
    fail:
        *plen = len;
        return -1;
    }
    *plen = len;
    return c;
}

int __utf8_get(const uint8_t *p, size_t *plen)
{
    size_t len;
    int c;

    c = p[0];
    if (c < 0xc0) {
        len = 1;
    } else if (c < 0xe0) {
        c = ((p[0] & 0x1f) << 6) | (p[1] & 0x3f);
        len = 2;
    } else if (c < 0xf0) {
        c = ((p[0] & 0x0f) << 12) | ((p[1] & 0x3f) << 6) | (p[2] & 0x3f);
        len = 3;
    } else if (c < 0xf8) {
        c = ((p[0] & 0x07) << 18) | ((p[1] & 0x3f) << 12) | ((p[2] & 0x3f) << 6) | (p[3] & 0x3f);
        len = 4;
    } else {
        len = 1;
    }
    *plen = len;
    return c;
}

