char CRC7(const char *data, int length) {
  char crc = 0;
  for (int i = 0; i < length; i++) {
    crc = m_CRC7Table[(crc << 1) ^ data[i]];
  }
  return crc;
}

unsigned short CRC16(const char *data, int length) {
  unsigned short crc = 0;
  for (int i = 0; i < length; i++) {
    crc = (crc << 8) ^ m_CRC16Table[((crc >> 8) ^ data[i]) & 0x00FF];
  }
  return crc;
}

