static uint64_t htonll (uint64_t value) {
  #if __BYTE_ORDER__ == __ORDER_LITTLE_ENDIAN__
    return ((uint64_t)htonl((uint32_t)(value >> 32))) |
           ((uint64_t)htonl((uint32_t)(value & 0xFFFFFFFF)) << 32);
  #else
    return value;
  #endif
  }

ssize_t recv_all (int client_fd, void *buf, size_t n, uint8_t require_first) {
  char *p = buf;
  size_t total = 0;

  // Track time of last meaningful network update
  // Used to handle timeout when client is stalling
  int64_t last_update_time = get_program_time();

  // If requested, exit early when first byte not immediately available
  if (require_first) {
    ssize_t r = recv(client_fd, p, 1, MSG_PEEK);
    if (r <= 0) {
      if (r < 0 && (errno == EAGAIN || errno == EWOULDBLOCK)) {
        return 0; // no first byte available yet
      }
      return -1; // error or connection closed
    }
  }

  // Busy-wait (with task yielding) until we get exactly n bytes
  while (total < n) {
    ssize_t r = recv(client_fd, p + total, n - total, 0);
    if (r < 0) {
      if (errno == EAGAIN || errno == EWOULDBLOCK) {
        // handle network timeout
        if (get_program_time() - last_update_time > NETWORK_TIMEOUT_TIME) {
          disconnectClient(&client_fd, -1);
          return -1;
        }
        task_yield();
        continue;
      } else {
        total_bytes_received += total;
        return -1; // real error
      }
    } else if (r == 0) {
      // connection closed before full read
      total_bytes_received += total;
      return total;
    }
    total += r;
    last_update_time = get_program_time();
  }

  total_bytes_received += total;
  return total; // got exactly n bytes
}

void discard_all (int client_fd, size_t remaining, uint8_t require_first) {
  while (remaining > 0) {
    size_t recv_n = remaining > MAX_RECV_BUF_LEN ? MAX_RECV_BUF_LEN : remaining;
    ssize_t received = recv_all(client_fd, recv_buffer, recv_n, require_first);
    if (received < 0) return;
    if (received > remaining) return;
    remaining -= received;
    require_first = false;
  }
}

ssize_t writeByte (int client_fd, uint8_t byte) {
  return send_all(client_fd, &byte, 1);
}

ssize_t writeUint16 (int client_fd, uint16_t num) {
  uint16_t be = htons(num);
  return send_all(client_fd, &be, sizeof(be));
}

ssize_t writeUint32 (int client_fd, uint32_t num) {
  uint32_t be = htonl(num);
  return send_all(client_fd, &be, sizeof(be));
}

ssize_t writeUint64 (int client_fd, uint64_t num) {
  uint64_t be = htonll(num);
  return send_all(client_fd, &be, sizeof(be));
}

ssize_t writeFloat (int client_fd, float num) {
  uint32_t bits;
  memcpy(&bits, &num, sizeof(bits));
  bits = htonl(bits);
  return send_all(client_fd, &bits, sizeof(bits));
}

ssize_t writeDouble (int client_fd, double num) {
  uint64_t bits;
  memcpy(&bits, &num, sizeof(bits));
  bits = htonll(bits);
  return send_all(client_fd, &bits, sizeof(bits));
}

uint16_t readUint16 (int client_fd) {
  recv_count = recv_all(client_fd, recv_buffer, 2, false);
  return ((uint16_t)recv_buffer[0] << 8) | recv_buffer[1];
}

static DWORD WINAPI ExitCountdownThread(LPVOID lpParam) {
    int seconds = (int)(intptr_t)lpParam;
    
    LOG_INFO("PluginExit: Countdown started (%d seconds)", seconds);
    
    while (seconds > 0 && g_exitInProgress) {
        /* Build display: prefix + number + suffix */
        wchar_t countdownNum[16];
        _snwprintf_s(countdownNum, 16, _TRUNCATE, L"%d", seconds);
        
        if (g_dataCS) {
            EnterCriticalSection(g_dataCS);
            
            size_t prefixLen = g_exitPrefix ? wcslen(g_exitPrefix) : 0;
            size_t suffixLen = g_exitSuffix ? wcslen(g_exitSuffix) : 0;
            size_t numLen = wcslen(countdownNum);
            size_t totalLen = prefixLen + numLen + suffixLen + 1;
            
            if (g_pluginDisplayText == NULL || g_pluginDisplayTextLen < totalLen) {
                wchar_t* newBuf = (wchar_t*)realloc(g_pluginDisplayText, totalLen * sizeof(wchar_t));
                if (newBuf) {
                    g_pluginDisplayText = newBuf;
                    g_pluginDisplayTextLen = totalLen;
                }
            }
            
            if (g_pluginDisplayText) {
                g_pluginDisplayText[0] = L'\0';
                if (g_exitPrefix) wcsncat_s(g_pluginDisplayText, totalLen, g_exitPrefix, prefixLen);
                wcsncat_s(g_pluginDisplayText, totalLen, countdownNum, numLen);
                if (g_exitSuffix) wcsncat_s(g_pluginDisplayText, totalLen, g_exitSuffix, suffixLen);
                g_hasPluginData = TRUE;
            }
            
            LeaveCriticalSection(g_dataCS);
        }
        
        if (g_notifyWnd) {
            InvalidateRect(g_notifyWnd, NULL, FALSE);
        }
        
        Sleep(1000);
        seconds--;
    }
    
    if (g_exitInProgress) {
        LOG_INFO("PluginExit: Countdown complete, requesting exit");
        if (g_notifyWnd) {
            PostMessage(g_notifyWnd, CLOCK_WM_PLUGIN_EXIT, 0, 0);
        }
    }
    
    g_exitInProgress = FALSE;
    return 0;
}

void PluginExit_Init(HWND hwnd, CRITICAL_SECTION* dataCS) {
    g_notifyWnd = hwnd;
    g_dataCS = dataCS;
    g_exitInProgress = FALSE;
    g_exitThread = NULL;
    g_exitPrefix = NULL;
    g_exitSuffix = NULL;
}

void PluginExit_Shutdown(void) {
    PluginExit_Cancel();
    g_notifyWnd = NULL;
    g_dataCS = NULL;
}

BOOL PluginExit_IsInProgress(void) {
    return g_exitInProgress;
}

BOOL PluginExit_ParseTag(wchar_t* text, int* textLen, size_t maxLen) {
    if (!text || !textLen) return FALSE;
    
    /* Cancel any existing countdown first to avoid race condition */
    if (g_exitInProgress) {
        PluginExit_Cancel();
    }
    
    wchar_t* start = wcsstr(text, L"<exit>");
    wchar_t* end = wcsstr(text, L"</exit>");
    
    if (!start || !end || end <= start) {
        return FALSE;
    }
    
    /* Parse countdown seconds (default 3) */
    int seconds = 3;
    wchar_t* numStart = start + 6;
    BOOL validNumber = TRUE;
    
    if (numStart < end) {
        /* Skip whitespace */
        while (numStart < end && (*numStart == L' ' || *numStart == L'\t')) {
            numStart++;
        }
        
        if (numStart < end) {
            /* Validate numeric content */
            wchar_t* p = numStart;
            while (p < end && *p != L' ' && *p != L'\t') {
                if (*p < L'0' || *p > L'9') {
                    validNumber = FALSE;
                    break;
                }
                p++;
            }
            
            if (validNumber) {
                int parsed = _wtoi(numStart);
                if (parsed > 0) {
                    seconds = parsed;
                } else {
                    validNumber = FALSE;
                }
            }
        }
    }
    
    if (!validNumber) {
        return FALSE;
    }
    
    /* Save prefix (text before <exit>) */
    size_t prefixLen = start - text;
    if (g_exitPrefix) {
        free(g_exitPrefix);
        g_exitPrefix = NULL;
    }
    if (prefixLen > 0) {
        g_exitPrefix = (wchar_t*)malloc((prefixLen + 1) * sizeof(wchar_t));
        if (g_exitPrefix) {
            wcsncpy(g_exitPrefix, text, prefixLen);
            g_exitPrefix[prefixLen] = L'\0';
        } else {
            LOG_WARNING("PluginExit: Failed to allocate prefix buffer (%zu bytes)", (prefixLen + 1) * sizeof(wchar_t));
        }
    }
    
    /* Save suffix (text after </exit>) */
    wchar_t* suffixStart = end + 7;
    if (g_exitSuffix) {
        free(g_exitSuffix);
        g_exitSuffix = NULL;
    }
    if (*suffixStart) {
        size_t suffixLen = wcslen(suffixStart);
        g_exitSuffix = (wchar_t*)malloc((suffixLen + 1) * sizeof(wchar_t));
        if (g_exitSuffix) {
            wcsncpy(g_exitSuffix, suffixStart, suffixLen);
            g_exitSuffix[suffixLen] = L'\0';
        } else {
            LOG_WARNING("PluginExit: Failed to allocate suffix buffer (%zu bytes)", (suffixLen + 1) * sizeof(wchar_t));
        }
    }
    
    /* Replace <exit>N</exit> with just N */
    wchar_t countdownNum[16];
    _snwprintf_s(countdownNum, 16, _TRUNCATE, L"%d", seconds);
    
    size_t suffixLen = wcslen(suffixStart);
    size_t numLen = wcslen(countdownNum);
    size_t newLen = prefixLen + numLen + suffixLen + 1;
    
    if (newLen <= maxLen) {
        memmove(start + numLen, suffixStart, (suffixLen + 1) * sizeof(wchar_t));
        memcpy(start, countdownNum, numLen * sizeof(wchar_t));
        *textLen = (int)(prefixLen + numLen + suffixLen);
    }
    
    /* Start countdown thread */
    g_exitInProgress = TRUE;
    g_exitThread = CreateThread(NULL, 0, ExitCountdownThread, 
                                (LPVOID)(intptr_t)seconds, 0, NULL);
    if (!g_exitThread) {
        g_exitInProgress = FALSE;
        LOG_ERROR("PluginExit: Failed to create countdown thread");
        return FALSE;
    }
    
    LOG_INFO("PluginExit: Started %d second countdown", seconds);
    return TRUE;
}

void PluginExit_Cancel(void) {
    if (!g_exitInProgress) return;
    
    g_exitInProgress = FALSE;
    
    /* Wait for thread */
    if (g_exitThread) {
        DWORD result = WaitForSingleObject(g_exitThread, 3000);
        if (result != WAIT_OBJECT_0) {
            LOG_ERROR("PluginExit: Thread did not terminate cleanly");
        }
        CloseHandle(g_exitThread);
        g_exitThread = NULL;
    }
    
    /* Cleanup templates */
    if (g_exitPrefix) {
        free(g_exitPrefix);
        g_exitPrefix = NULL;
    }
    if (g_exitSuffix) {
        free(g_exitSuffix);
        g_exitSuffix = NULL;
    }
    
    LOG_INFO("PluginExit: Countdown cancelled");
}

