static void
bm25_cache_invalidation_callback(
		Datum arg		 pg_attribute_unused(),
		int cacheid		 pg_attribute_unused(),
		uint32 hashvalue pg_attribute_unused())
{
	oid_cache_state = CACHE_UNKNOWN;
}

static bool
lookup_bm25_oids_internal(BM25OidCache *cache)
{
	HeapTuple tuple;
	List	 *opname;

	memset(cache, 0, sizeof(BM25OidCache));

	/* Look up bm25 access method */
	tuple = SearchSysCache1(AMNAME, CStringGetDatum("bm25"));
	if (HeapTupleIsValid(tuple))
	{
		cache->bm25_am_oid = ((Form_pg_am)GETSTRUCT(tuple))->oid;
		ReleaseSysCache(tuple);
	}

	if (!OidIsValid(cache->bm25_am_oid))
		return false;

	/* Look up bm25query type using the search path */
	cache->tpquery_type_oid = TypenameGetTypid("bm25query");
	if (!OidIsValid(cache->tpquery_type_oid))
		return false;

	/* Look up the <@> operator for (text, bm25query) */
	opname = list_make1(makeString("<@>"));
	cache->text_tpquery_operator_oid =
			OpernameGetOprid(opname, TEXTOID, cache->tpquery_type_oid);
	list_free(opname);

	/* Look up the <@> operator for (text, text) */
	opname						  = list_make1(makeString("<@>"));
	cache->text_text_operator_oid = OpernameGetOprid(opname, TEXTOID, TEXTOID);
	list_free(opname);

	return true;
}

static bool
get_bm25_oids(BM25OidCache *cache)
{
	/* Register invalidation callbacks on first call */
	if (!invalidation_registered)
	{
		CacheRegisterSyscacheCallback(
				AMOID, bm25_cache_invalidation_callback, (Datum)0);
		CacheRegisterSyscacheCallback(
				TYPEOID, bm25_cache_invalidation_callback, (Datum)0);
		invalidation_registered = true;
	}

	/* Fast path: use cached result */
	switch (oid_cache_state)
	{
	case CACHE_NOT_FOUND:
		return false;
	case CACHE_VALID:
		*cache = cached_oids;
		return true;
	case CACHE_UNKNOWN:
		break;
	}

	/* Do the actual lookup */
	if (!lookup_bm25_oids_internal(cache))
	{
		oid_cache_state = CACHE_NOT_FOUND;
		return false;
	}

	cached_oids		= *cache;
	oid_cache_state = CACHE_VALID;
	return true;
}

static Oid
find_bm25_index_for_column(Oid relid, AttrNumber attnum, Oid bm25_am_oid)
{
	Relation	indexRelation;
	SysScanDesc scan;
	HeapTuple	indexTuple;
	Oid			result		= InvalidOid;
	int			index_count = 0;
	ScanKeyData scanKey;

	if (!OidIsValid(bm25_am_oid))
		return InvalidOid;

	indexRelation = table_open(IndexRelationId, AccessShareLock);

	ScanKeyInit(
			&scanKey,
			Anum_pg_index_indrelid,
			BTEqualStrategyNumber,
			F_OIDEQ,
			ObjectIdGetDatum(relid));

	scan = systable_beginscan(
			indexRelation, IndexIndrelidIndexId, true, NULL, 1, &scanKey);

	while ((indexTuple = systable_getnext(scan)) != NULL)
	{
		Form_pg_index indexForm = (Form_pg_index)GETSTRUCT(indexTuple);
		Oid			  indexOid	= indexForm->indexrelid;
		HeapTuple	  classTuple;
		Form_pg_class classForm;

		classTuple = SearchSysCache1(RELOID, ObjectIdGetDatum(indexOid));
		if (!HeapTupleIsValid(classTuple))
			continue;

		classForm = (Form_pg_class)GETSTRUCT(classTuple);

		if (classForm->relam == bm25_am_oid)
		{
			int nkeys = indexForm->indnatts;

			for (int i = 0; i < nkeys; i++)
			{
				if (indexForm->indkey.values[i] == attnum)
				{
					index_count++;
					if (result == InvalidOid)
						result = indexOid;
					break;
				}
			}
		}
		ReleaseSysCache(classTuple);
	}

	systable_endscan(scan);
	table_close(indexRelation, AccessShareLock);

	if (index_count > 1)
		ereport(WARNING,
				(errmsg("multiple BM25 indexes exist on the same column"),
				 errhint("Use explicit to_bm25query('query', 'index_name') "
						 "to specify which index to use.")));

	return result;
}

static bool
get_var_relation_and_attnum(
		Var *var, Query *query, Oid *relid, AttrNumber *attnum)
{
	RangeTblEntry *rte;

	if (var->varno < 1 || var->varno > list_length(query->rtable))
		return false;

	rte = rt_fetch(var->varno, query->rtable);
	if (rte->rtekind != RTE_RELATION)
		return false;

	*relid	= rte->relid;
	*attnum = var->varattno;
	return true;
}

static Oid
find_index_for_var(Var *var, ResolveIndexContext *context)
{
	Oid		   relid;
	AttrNumber attnum;

	if (!get_var_relation_and_attnum(var, context->query, &relid, &attnum))
		return InvalidOid;

	return find_bm25_index_for_column(
			relid, attnum, context->oid_cache->bm25_am_oid);
}

static Const *
create_resolved_tpquery_const(Const *original, Oid index_oid)
{
	TpQuery *old_tpquery = (TpQuery *)DatumGetPointer(original->constvalue);
	char	*query_text	 = get_tpquery_text(old_tpquery);
	TpQuery *new_tpquery = create_tpquery(query_text, index_oid);

	return makeConst(
			original->consttype,
			original->consttypmod,
			original->constcollid,
			VARSIZE(new_tpquery),
			PointerGetDatum(new_tpquery),
			false,
			false);
}

static OpExpr *
create_opexpr(Oid opno, Node *left, Node *right, Oid inputcollid, int location)
{
	OpExpr *new_opexpr = makeNode(OpExpr);

	new_opexpr->opno		 = opno;
	new_opexpr->opfuncid	 = get_opcode(opno);
	new_opexpr->opresulttype = FLOAT8OID;
	new_opexpr->opretset	 = false;
	new_opexpr->opcollid	 = InvalidOid;
	new_opexpr->inputcollid	 = inputcollid;
	new_opexpr->args		 = list_make2(copyObject(left), right);
	new_opexpr->location	 = location;

	return new_opexpr;
}

static Node *
transform_tpquery_opexpr(OpExpr *opexpr, ResolveIndexContext *context)
{
	BM25OidCache *oids = context->oid_cache;
	Node		 *left;
	Node		 *right;
	Const		 *constNode;
	TpQuery		 *tpquery;
	Oid			  index_oid;
	Const		 *new_const;

	if (opexpr->opno != oids->text_tpquery_operator_oid)
		return NULL;
	if (list_length(opexpr->args) != 2)
		return NULL;

	left  = linitial(opexpr->args);
	right = lsecond(opexpr->args);

	/* Try to simplify function calls (e.g., to_bm25query()) to constants */
	if (IsA(right, FuncExpr))
		right = eval_const_expressions(NULL, right);

	if (!IsA(right, Const))
		return NULL;

	constNode = (Const *)right;
	if (constNode->consttype != oids->tpquery_type_oid ||
		constNode->constisnull)
		return NULL;

	tpquery = (TpQuery *)DatumGetPointer(constNode->constvalue);
	if (OidIsValid(tpquery->index_oid))
		return NULL; /* Already resolved */

	if (!IsA(left, Var))
		return NULL;

	index_oid = find_index_for_var((Var *)left, context);
	if (!OidIsValid(index_oid))
		return NULL;

	new_const = create_resolved_tpquery_const(constNode, index_oid);
	return (Node *)create_opexpr(
			opexpr->opno,
			left,
			(Node *)new_const,
			opexpr->inputcollid,
			opexpr->location);
}

static Node *
transform_text_text_opexpr(OpExpr *opexpr, ResolveIndexContext *context)
{
	BM25OidCache *oids = context->oid_cache;
	Node		 *left;
	Node		 *right;
	Var			 *var;
	Const		 *text_const;
	Oid			  index_oid;
	char		 *query_text;
	TpQuery		 *tpquery;
	Const		 *tpquery_const;

	if (opexpr->opno != oids->text_text_operator_oid)
		return NULL;
	if (list_length(opexpr->args) != 2)
		return NULL;

	left  = linitial(opexpr->args);
	right = lsecond(opexpr->args);

	if (!IsA(left, Var) || !IsA(right, Const))
		return NULL;

	var		   = (Var *)left;
	text_const = (Const *)right;

	if (text_const->consttype != TEXTOID || text_const->constisnull)
		return NULL;

	index_oid = find_index_for_var(var, context);
	if (!OidIsValid(index_oid))
		return NULL;

	query_text = TextDatumGetCString(text_const->constvalue);
	tpquery	   = create_tpquery(query_text, index_oid);
	pfree(query_text);

	tpquery_const = makeConst(
			oids->tpquery_type_oid,
			-1,
			InvalidOid,
			-1, /* varlena type */
			PointerGetDatum(tpquery),
			false,
			false);

	return (Node *)create_opexpr(
			oids->text_tpquery_operator_oid,
			left,
			(Node *)tpquery_const,
			opexpr->inputcollid,
			opexpr->location);
}

bool delete_walk_entry(Walk_Entry entry)
{
    return delete_file(entry.path);
}

bool delete_directory_recursively(const char *dir_path)
{
    return walk_dir(dir_path, delete_walk_entry, .post_order = true);
}

bool build_and_run_test(const char *test_name, bool record)
{
    bool result = true;
    Cmd cmd = {0};
    String_Builder src = {0};
    String_Builder dst = {0};
    String_View src_sv = {0};
    String_View dst_sv = {0};
#ifdef _WIN32
    const char *src_stdout_path  = temp_sprintf("%s%s.win32.stdout.txt", BUILD_FOLDER TESTS_FOLDER, test_name);
    const char *dst_stdout_path  = temp_sprintf("%s%s.win32.stdout.txt", TESTS_FOLDER, test_name);
    const char *test_stdout_path = temp_sprintf("../%s.win32.stdout.txt", test_name);
#else
    const char *src_stdout_path  = temp_sprintf("%s%s.stdout.txt", BUILD_FOLDER TESTS_FOLDER, test_name);
    const char *dst_stdout_path  = temp_sprintf("%s%s.stdout.txt", TESTS_FOLDER, test_name);
    const char *test_stdout_path = temp_sprintf("../%s.stdout.txt", test_name);
#endif // _WIN32
    const char *bin_path         = temp_sprintf("%s%s", BUILD_FOLDER TESTS_FOLDER, test_name);
    const char *src_path         = temp_sprintf("%s%s.c", TESTS_FOLDER, test_name);
    const char *test_cwd_path    = temp_sprintf("%s%s%s.cwd", BUILD_FOLDER, TESTS_FOLDER, test_name);

    nob_cc(&cmd);
    nob_cc_flags(&cmd);
    nob_cc_output(&cmd, bin_path);
    nob_cc_inputs(&cmd, src_path);
    if (!cmd_run(&cmd)) return_defer(false);

    if (file_exists(test_cwd_path)) {
        if (!delete_directory_recursively(test_cwd_path)) return_defer(false);
    }
    if (!mkdir_if_not_exists(test_cwd_path)) return_defer(false);
    if (!set_current_dir(test_cwd_path)) return_defer(false);
#ifdef _WIN32
    cmd_append(&cmd, temp_sprintf("../%s.exe", test_name));
#else
    cmd_append(&cmd, temp_sprintf("../%s", test_name));
#endif // _WIN32
    if (!cmd_run(&cmd, .stdout_path = test_stdout_path)) return_defer(false);
    if (!set_current_dir("../../../")) return_defer(false);

    // TODO: implement record/replay testing for windows
    if (record) {
        if (!copy_file(src_stdout_path, dst_stdout_path)) return_defer(false);
    } else {
        // TODO: it would be cool to have a portable diff utility in here.
        if (!read_entire_file(src_stdout_path, &src)) return_defer(false);
        if (!read_entire_file(dst_stdout_path, &dst)) return_defer(false);

        src_sv = sb_to_sv(src);
        dst_sv = sb_to_sv(dst);

        if (!sv_eq(src_sv, dst_sv)) {
            nob_log(ERROR, "UNEXPECTED OUTPUT!");
            nob_log(ERROR, "EXPECTED:");
            fprintf(stderr, SV_Fmt, SV_Arg(dst_sv));
            nob_log(ERROR, "ACTUAL:");
            fprintf(stderr, SV_Fmt, SV_Arg(src_sv));
            return_defer(false);
        }
    }

    nob_log(INFO, "--- %s finished ---", bin_path);

defer:
    free(dst.items);
    free(src.items);
    free(cmd.items);
    return result;
}

void commands_reset(Commands *commands)
{
    commands->count = 0;
    commands->picked = false;
}

bool command_loc(const char *file, int line, const char *arg, Commands *commands, const char *name, const char *signature, const char *description)
{
    if (commands->picked) {
        fprintf(stderr, "%s:%d: ASSERTION FAILED: the branch for command `%s` fell through.\n", commands->picked_at_file, commands->picked_at_line, commands->picked_name);
        fprintf(stderr, "%s:%d: NOTE: the execution proceeded to here, but the command was already picked.\n", file, line);
        abort();
    }
    Command command = {
        .name = name,
        .signature = signature,
        .description = description,
    };
    da_append(commands, command);
    commands->picked_name    = name;
    commands->picked_at_line = line;
    commands->picked_at_file = file;
    commands->picked         = (strcmp(arg, name) == 0);
    return commands->picked;
}

void print_available_commands(Commands commands)
{
    size_t max_name_width = 0;
    size_t max_sign_width = 0;
    da_foreach(Command, command, &commands) {
        size_t name_width = strlen(command->name);
        size_t sign_width = strlen(command->signature);
        if (name_width > max_name_width) max_name_width = name_width;
        if (sign_width > max_sign_width) max_sign_width = sign_width;
    }
    nob_log(INFO, "Available commands:");
    da_foreach(Command, command, &commands) {
        nob_log(INFO, "    %-*s %-*s - %s", (int)max_name_width, command->name, (int)max_sign_width, command->signature, command->description);
    }
}

void progress_report(size_t max_procs)
{
    size_t bar_max = 20;
    size_t bar_current = bar_max*jobs_counter/jobs_max;
    static const char *spinner[] = {"⠋", "⠙", "⠹", "⠸", "⠼", "⠴", "⠦", "⠧", "⠇", "⠏"};
    printf("\rProgress: ");
    for (size_t j = 0;           j < bar_current; ++j) printf("#");
    for (size_t j = bar_current; j < bar_max;     ++j) printf(".");
    printf(" %s Jobs: %zu/%zu, max_procs=%zu", spinner[jobs_counter%ARRAY_LEN(spinner)], jobs_counter, jobs_max, max_procs);
    fflush(stdout);
}

void progress_start(void)
{
    nob_minimal_log_level = WARNING;
}

void progress_finish(void)
{
    printf("\n"); // Break the progress reporting
    nob_minimal_log_level = INFO;
}

bool single_build(Config config)
{
    const char *worker_type = config.worker_type;
    size_t worker_count = config.worker_count;
    size_t max_procs = config.max_procs;
#ifdef _WIN32
    const char *worker_path = temp_sprintf(BUILD_FOLDER"%s.exe", worker_type);
#else
    const char *worker_path = temp_sprintf(BUILD_FOLDER"%s", worker_type);
#endif

    for (size_t i = 0; i < worker_count; ++i) {
        cmd_append(&cmd, worker_path);
        if (!cmd_run(&cmd, .async = &procs, .max_procs = max_procs)) return false;
        jobs_counter += 1;
        progress_report(max_procs);
    }

    if (!nob_procs_flush(&procs)) return false;

    return true;
}

static int flush(struct savectx *ctx) {
    if (ctx->nentries == 0) {
        ctx->buf.len = 0;
        return 0;
    }
    // Make sure that there's enough space in the dst buffer to store the
    // header (16 bytes) and the compressed data.
    size_t bounds = LZ4_compressBound(ctx->buf.len);
    buf_ensure(&ctx->dst, 16+bounds);
    // Compress the block
    uint32_t len = LZ4_compress_default((char*)ctx->buf.data, 
        (char*)ctx->dst.data+16, ctx->buf.len, bounds);
    // The block is now compressed.
    // Genreate a checksum of the compressed data.
    uint32_t crc = crc32(ctx->dst.data+16, len);
    // Write the 16 byte header
    // (0-3) 'POGO' tag
    memcpy(ctx->dst.data, "POGO", 4);
    // (4-7) Checksum
    write_u32(ctx->dst.data+4, crc);
    // (8-11) Len of decompressed data 
    write_u32(ctx->dst.data+8, ctx->buf.len);
    // (12-15) Len of compressed data 
    write_u32(ctx->dst.data+12, len);
    // The rest of the dst buffer contains the compressed bytes
    uint8_t *p = (uint8_t*)ctx->dst.data;
    uint8_t *end = p + len+16;
    bool ok = true;
    pthread_mutex_lock(ctx->lock);
    while (p < end) {
        ssize_t n = write(ctx->fd, p, end-p);
        if (n < 0) {
            ok = false;
            break;
        }
        p += n;
    }
    pthread_mutex_unlock(ctx->lock);
    ctx->buf.len = 0;
    ctx->nentries = 0;
    return ok ? 0 : -1;
}

static int save_entry(int shard, int64_t time, const void *key, size_t keylen,
    const void *value, size_t valuelen, int64_t expires, uint32_t flags,
    uint64_t cas, void *udata)
{
    (void)shard;
    struct savectx *ctx = udata;
    buf_append_byte(&ctx->buf, 0); // entry type. zero=k/v string pair;
    buf_append_uvarint(&ctx->buf, keylen);
    buf_append(&ctx->buf, key, keylen);
    buf_append_uvarint(&ctx->buf, valuelen);
    buf_append(&ctx->buf, value, valuelen);
    if (expires > 0) {
        int64_t ttl = expires-time;
        assert(ttl > 0);
        buf_append_uvarint(&ctx->buf, ttl);
    } else {
        buf_append_uvarint(&ctx->buf, 0);
    }
    buf_append_uvarint(&ctx->buf, flags);
    buf_append_uvarint(&ctx->buf, cas);
    ctx->nentries++;
    return POGOCACHE_ITER_CONTINUE;
}

static void *thsave(void *arg) {
    struct savectx *ctx = arg;
    for (int i = 0; i < ctx->count; i++) {
        int shardidx = ctx->start+i;
        struct pogocache_iter_opts opts = {
            .oneshard = true,
            .oneshardidx = shardidx,
            .time = sys_now(),
            .entry = save_entry,
            .udata = ctx,
        };
        // write the unix timestamp before entries
        buf_append_uvarint(&ctx->buf, sys_unixnow());
        int status = pogocache_iter(cache, &opts);
        if (status == POGOCACHE_CANCELED) {
            goto done;
        }
        if (flush(ctx) == -1) {
            goto done;
        }
    }
    ctx->ok = true;
done:
    buf_clear(&ctx->buf);
    buf_clear(&ctx->dst);
    ctx->errnum = errno;
    return 0;
}

static bool load_block(struct cblock *block, struct loadctx *ctx) {
    (void)ctx;
    bool ok = false;

    int64_t now = sys_now();
    int64_t unixnow = sys_unixnow();

    // decompress block
    char *ddata = xmalloc(block->dlen);
    int ret = LZ4_decompress_safe(block->cdata.data, ddata, block->cdata.len, 
        block->dlen);
    if (ret < 0 || (size_t)ret != block->dlen) {
        printf(". bad compressed block\n");
        goto done;
    }
    buf_clear(&block->cdata);
    uint8_t *p = (void*)ddata;
    uint8_t *e = p + block->dlen;

    int n;
    uint64_t x;
    // read unix time
    n = varint_read_u64(p, e-p, &x);
    if (n <= 0 || (int64_t)x < 0) {
        printf(". bad unix time\n");
        goto done;
    }
    p += n;

    int64_t unixtime = x;
    // printf(". unixtime=%lld\n", unixtime);

    // Read each entry from decompressed data
    while (e > p) {
        /////////////////////
        // kind
        uint8_t kind = *(p++);

        if (kind != 0) {
            // only k/v strings allowed at this time.
            printf(">> %d\n", kind);
            printf(". unknown kind\n");
            goto done;
        }
        /////////////////////
        // key
        n = varint_read_u64(p, e-p, &x);
        if (n <= 0 || x > SIZE_MAX) {
            goto done;
        }
        p += n;
        size_t keylen = x;
        if ((size_t)(e-p) < keylen) {
            goto done;
        }
        const uint8_t *key = p;
        p += keylen;
        /////////////////////
        // val
        n = varint_read_u64(p, e-p, &x);
        if (n <= 0 || x > SIZE_MAX) {
            goto done;
        }
        p += n;
        size_t vallen = x;
        if ((size_t)(e-p) < vallen) {
            goto done;
        }
        const uint8_t *val = p;
        p += vallen;
        /////////////////////
        // ttl
        n = varint_read_u64(p, e-p, &x);
        if (n <= 0 || (int64_t)x < 0) {
            goto done;
        }
        int64_t ttl = x;
        p += n;
        /////////////////////
        // flags
        n = varint_read_u64(p, e-p, &x);
        if (n <= 0 || x > UINT32_MAX) {
            goto done;
        }
        uint32_t flags = x;
        p += n;
        /////////////////////
        // cas
        n = varint_read_u64(p, e-p, &x);
        if (n <= 0) {
            goto done;
        }
        uint64_t cas = x;
        p += n;
        if (ttl > 0) {
            int64_t unixexpires = int64_add_clamp(unixtime, ttl);
            if (unixexpires < unixnow) {
                // already expired, skip this entry
                ctx->nexpired++;
                continue;
            }
            ttl = unixexpires-unixnow;
        }
        struct pogocache_store_opts opts = {
            .flags = flags,
            .time = now,
            .ttl = ttl,
            .cas = cas,
        };
        // printf("[%.*s]=[%.*s]\n", (int)keylen, key, (int)vallen, val);
        int ret = pogocache_store(cache, key, keylen, val, vallen, &opts);
        (void)ret;
        assert(ret == POGOCACHE_INSERTED || ret == POGOCACHE_REPLACED);
        ctx->ninserted++;
    }
    ok = true;
done:
    buf_clear(&block->cdata);
    xfree(ddata);
    if (!ok) {
        printf(". bad block\n");
    }
    return ok;
}

static void *thload(void *arg) {
    struct loadctx *ctx = arg;
    pthread_mutex_lock(ctx->lock);
    while (1) {
        if (*ctx->failure) {
            break;
        }
        if (*ctx->nblocks > 0) {
            // Take a block for processing
            struct cblock block = ctx->blocks[(*ctx->nblocks)-1];
            (*ctx->nblocks)--;
            pthread_mutex_unlock(ctx->lock);
            pthread_cond_broadcast(ctx->cond); // notify reader thread
            ctx->ok = load_block(&block, ctx);
            pthread_mutex_lock(ctx->lock);
            if (!ctx->ok) {
                *ctx->failure = true;
                break;
            }
            // next block
            continue;
        }
        if (*ctx->donereading) {
            break;
        }
        pthread_cond_wait(ctx->cond, ctx->lock);
    }
    pthread_mutex_unlock(ctx->lock);
    pthread_cond_broadcast(ctx->cond); // notify reader thread
    if (!ctx->ok) {
        ctx->errnum = errno;
    }
    return 0;
}

bool cleanwork(const char *persist) {
    if (*persist == '\0') {
        return false;
    }
    bool ok = false;
    char *path = xmalloc(strlen(persist)+1);
    strcpy(path, persist);
    char *dirpath = dirname(path);
    DIR *dir = opendir(dirpath);
    if (!dir) {
        perror("# opendir");
        goto done;
    }
    struct dirent *entry;
    while ((entry = readdir(dir))) {
        if (entry->d_type != DT_REG) {
            continue;
        }
        const char *ext = ".pogocache.work";
        if (strlen(entry->d_name) < strlen(ext) ||
            strcmp(entry->d_name+strlen(entry->d_name)-strlen(ext), ext) != 0)
        {
            continue;
        }
        size_t filepathcap = strlen(dirpath)+1+strlen(entry->d_name)+1;
        char *filepath = xmalloc(filepathcap);
        snprintf(filepath, filepathcap, "%s/%s", dirpath, entry->d_name);
        if (unlink(filepath) == 0) {
            printf("# deleted work file %s\n", filepath);
        } else {
            perror("# unlink");
        }
        xfree(filepath);
    }
    ok = true;
done:
    if (dir) {
        closedir(dir);
    }
    xfree(path);
    return ok;
}

static int64_t nanotime(struct timespec *ts) {
    int64_t x = ts->tv_sec;
    x *= 1000000000;
    x += ts->tv_nsec;
    return x;
}

static int64_t gettime(void) {
    struct timespec now = { 0 };
#ifdef __linux__
    clock_gettime(CLOCK_BOOTTIME, &now);
#elif defined(__APPLE__)
    clock_gettime(CLOCK_UPTIME_RAW, &now);
#else
    clock_gettime(CLOCK_MONOTONIC, &now);
#endif
    return nanotime(&now);
}

static int64_t getnow(void) {
    return gettime();
}

static uint64_t th64(const void *data, size_t len, uint64_t seed) {
    uint8_t*p=(uint8_t*)data,*e=p+len;
    uint64_t r=0x14020a57acced8b7,x,h=seed;
    while(p+8<=e)memcpy(&x,p,8),x*=r,p+=8,x=x<<31|x>>33,h=h*r^x,h=h<<31|h>>33;
    while(p<e)h=h*r^*(p++);
    return(h=h*r+len,h^=h>>31,h*=r,h^=h>>31,h*=r,h^=h>>31,h*=r,h);
}

uint8_t TFT_eSPI::tft_Read_8(void)
{
  uint8_t  ret = 0;

  for (uint8_t i = 0; i < 8; i++) {  // read results
    ret <<= 1;
    SCLK_L;
    if (digitalRead(TFT_MOSI)) ret |= 1;
    SCLK_H;
  }

  return ret;
}

bool TFT_eSPI::dmaBusy(void)
{
  if (!DMA_Enabled || !spiBusyCheck) return false;

  spi_transaction_t *rtrans;
  esp_err_t ret;
  uint8_t checks = spiBusyCheck;
  for (int i = 0; i < checks; ++i)
  {
    ret = spi_device_get_trans_result(dmaHAL, &rtrans, 0);
    if (ret == ESP_OK) spiBusyCheck--;
  }

  //Serial.print("spiBusyCheck=");Serial.println(spiBusyCheck);
  if (spiBusyCheck ==0) return false;
  return true;
}

void TFT_eSPI::dmaWait(void)
{
  if (!DMA_Enabled || !spiBusyCheck) return;
  spi_transaction_t *rtrans;
  esp_err_t ret;
  for (int i = 0; i < spiBusyCheck; ++i)
  {
    ret = spi_device_get_trans_result(dmaHAL, &rtrans, portMAX_DELAY);
    assert(ret == ESP_OK);
  }
  spiBusyCheck = 0;
}

void TFT_eSPI::pushPixelsDMA(uint16_t* image, uint32_t len)
{
  if ((len == 0) || (!DMA_Enabled)) return;

  dmaWait();

  if(_swapBytes) {
    for (uint32_t i = 0; i < len; i++) (image[i] = image[i] << 8 | image[i] >> 8);
  }

  // DMA byte count for transmit is 64Kbytes maximum, so to avoid this constraint
  // small transfers are performed using a blocking call until DMA capacity is reached.
  // User sketch can prevent blocking by managing pixel count and splitting into blocks
  // of 32768 pixels maximum. (equivalent to an area of ~320 x 100 pixels)
  bool temp = _swapBytes;
  _swapBytes = false;
  while(len>0x4000) { // Transfer 16-bit pixels in blocks if len*2 over 65536 bytes
    pushPixels(image, 0x400);
    len -= 0x400; image+= 0x400; // Arbitrarily send 1K pixel blocks (2Kbytes)
  }
  _swapBytes = temp;

  esp_err_t ret;
  static spi_transaction_t trans;

  memset(&trans, 0, sizeof(spi_transaction_t));

  trans.user = (void *)1;
  trans.tx_buffer = image;  //finally send the line data
  trans.length = len * 16;        //Data length, in bits
  trans.flags = 0;                //SPI_TRANS_USE_TXDATA flag

  ret = spi_device_queue_trans(dmaHAL, &trans, portMAX_DELAY);
  assert(ret == ESP_OK);

  spiBusyCheck++;
}

void TFT_eSPI::pushImageDMA(int32_t x, int32_t y, int32_t w, int32_t h, uint16_t const* image)
{
  if ((w == 0) || (h == 0) || (!DMA_Enabled)) return;

  uint16_t *buffer = (uint16_t*)image;
  uint32_t len = w*h;

  dmaWait();

  setAddrWindow(x, y, w, h);
  // DMA byte count for transmit is 64Kbytes maximum, so to avoid this constraint
  // small transfers are performed using a blocking call until DMA capacity is reached.
  // User sketch can prevent blocking by managing pixel count and splitting into blocks
  // of 32768 pixels maximum. (equivalent to an area of ~320 x 100 pixels)
  bool temp = _swapBytes;
  _swapBytes = false;
  while(len>0x4000) { // Transfer 16-bit pixels in blocks if len*2 over 65536 bytes
    pushPixels(buffer, 0x400);
    len -= 0x400; buffer+= 0x400; // Arbitrarily send 1K pixel blocks (2Kbytes)
  }
  _swapBytes = temp;

  esp_err_t ret;
  static spi_transaction_t trans;

  memset(&trans, 0, sizeof(spi_transaction_t));

  trans.user = (void *)1;
  trans.tx_buffer = buffer;   //Data pointer
  trans.length = len * 16;   //Data length, in bits
  trans.flags = 0;           //SPI_TRANS_USE_TXDATA flag

  ret = spi_device_queue_trans(dmaHAL, &trans, portMAX_DELAY);
  assert(ret == ESP_OK);

  spiBusyCheck++;
}

