bool func_col2_800A3A74(Vec3f* point, Vec3f** tri, Vec3f* normOut) {
    s32 pad;
    f32 temp1;
    bool ret = false;
    f32 temp_fv0;
    Vec3f vtx1;
    Vec3f vtx2;
    Vec3f vtx3;
    f32 ptx;
    f32 ptz;

    vtx1.x = (*tri)->x;
    vtx1.y = (*tri)->y;
    vtx1.z = (*tri)->z;
    tri++;
    vtx2.x = (*tri)->x;
    vtx2.y = (*tri)->y;
    vtx2.z = (*tri)->z;
    tri++;
    vtx3.x = (*tri)->x;
    vtx3.y = (*tri)->y;
    vtx3.z = (*tri)->z;
    tri++;

    ptx = point->x;
    ptz = point->z;

    temp1 = ((vtx2.z - vtx1.z) * (ptx - vtx2.x)) - ((vtx2.x - vtx1.x) * (ptz - vtx2.z));
    if (temp1 >= 0.0f) {
        if (((vtx3.x - vtx2.x) * (ptz - vtx3.z)) <= ((vtx3.z - vtx2.z) * (ptx - vtx3.x))) {
            if (((vtx1.x - vtx3.x) * (ptz - vtx1.z)) <= ((vtx1.z - vtx3.z) * (ptx - vtx1.x))) {
                ret = true;
                normOut->x = ((vtx2.y - vtx1.y) * (vtx3.z - vtx2.z)) - ((vtx2.z - vtx1.z) * (vtx3.y - vtx2.y));
                normOut->y = ((vtx2.z - vtx1.z) * (vtx3.x - vtx2.x)) - ((vtx2.x - vtx1.x) * (vtx3.z - vtx2.z));
                normOut->z = ((vtx2.x - vtx1.x) * (vtx3.y - vtx2.y)) - ((vtx2.y - vtx1.y) * (vtx3.x - vtx2.x));
                if ((normOut->x != 0.0f) || (normOut->y != 0.0f) || (normOut->z != 0.0f)) {
                    temp_fv0 = VEC3F_MAG(normOut);
                    if (temp_fv0 != 0) {
                        normOut->x = (normOut->x / temp_fv0) * 127.0f;
                        normOut->y = (normOut->y / temp_fv0) * 127.0f;
                        normOut->z = (normOut->z / temp_fv0) * 127.0f;
                    }
                }
            }
        }
    }
    return ret;
}

s32 osEepromWrite(OSMesgQueue* mq, u8 address, u8* buffer) {
    s32 ret = 0;
    int i;
    u8* ptr = (u8*) __osEepPifRam.ramarray;
    __OSContEepromFormat eepromformat;
    OSContStatus sdata;

    if (address > 0x40) {
        return -1;
    }

    __osSiGetAccess();
    ret = __osEepStatus(mq, &sdata);

    if (ret != 0 || sdata.type != 0x8000) {
        return 8;
    }

    while (sdata.status & 0x80) {
        __osEepStatus(mq, &sdata);
    }

    __osPackEepWriteData(address, buffer);

    ret = __osSiRawStartDma(OS_WRITE, &__osEepPifRam);
    osRecvMesg(mq, NULL, OS_MESG_BLOCK);

    for (i = 0; i < ARRLEN(__osEepPifRam.raw); i++) {
        __osEepPifRam.raw[i] = CONT_CMD_NOP;
    }

    __osEepPifRam.pifstatus = 0;
    ret = __osSiRawStartDma(OS_READ, &__osEepPifRam);
    __osContLastCmd = 5;
    osRecvMesg(mq, NULL, OS_MESG_BLOCK);

    for (i = 0; i < 4; i++) {
        ptr++;
    }

    eepromformat = *(__OSContEepromFormat*) ptr;
    ret = CHNL_ERR(eepromformat);
    __osSiRelAccess();
    return ret;
}

void proc_iterate(void (^itBlock)(uint64_t, bool*))
{
	uint64_t proc = ksymbol(allproc);
	while((proc = kread_ptr(proc + koffsetof(proc, list_next))))
	{
		bool stop = false;
		itBlock(proc, &stop);
		if(stop) return;
	}
}

uint64_t proc_self(void)
{
	static uint64_t gSelfProc = 0;
	static dispatch_once_t onceToken;
	dispatch_once(&onceToken, ^{
		gSelfProc = proc_find(getpid());
		// decrement ref count again, we assume proc_self will exist for the whole lifetime of this process
		proc_rele(gSelfProc);
	});
	return gSelfProc;
}

uint64_t get_pac_mask(uint64_t pointer) {
    uint64_t mask = 0;

    // Isolate relevant PAC bits
    uint64_t first_relevant = pointer >> 14;

    // Check each bit in the isolated PAC bits
    for (int i = 63; i >= 14; i--) {
        if ((first_relevant >> (i - 14)) & 1) {
            mask |= (1UL << i);
        } else {
            break;
        }
    }

    if (!mask) {
        return 0;
    }

    return mask;
}

struct k_posix_cred proc_get_posix_cred(uint64_t proc, bool iOS14)
{
    struct k_posix_cred pcred = {0};
    int ucred_off = iOS14 ? 0xF0 : 0xD8;
    uint64_t unPACed_ptr = kread_ptr(proc);
    uint64_t mask = get_pac_mask(unPACed_ptr);
    uint64_t ucred = kread_ptr(proc + ucred_off); // proc->ucred
    ucred |= mask;
    uint64_t posix_cred_kptr = ucred + 0x18; // ucred->posix_cred
    kreadbuf(posix_cred_kptr, &pcred, sizeof(struct k_posix_cred));
    return pcred;
}

void proc_set_posix_cred(uint64_t proc, struct k_posix_cred posix_cred, bool iOS14)
{
    int ucred_off = iOS14 ? 0xF0 : 0xD8;
    uint64_t unPACed_ptr = kread_ptr(proc);
    uint64_t mask = get_pac_mask(unPACed_ptr);
    uint64_t ucred = kread_ptr(proc + ucred_off); // proc->ucred
    ucred |= mask;
    uint64_t posix_cred_kptr = ucred + 0x18;
    kwritebuf(posix_cred_kptr, &posix_cred, sizeof(struct k_posix_cred));
}

