}

int fh_pkt4_parse(void *pkt_data, int pkt_len, struct sockaddr *saddr,
                  struct sockaddr *daddr, uint8_t *ttl,
                  struct tcphdr **tcph_ptr, int *tcp_payload_len)
{
    struct iphdr *iph;
    struct tcphdr *tcph;
    int iph_len, tcph_len;
    struct sockaddr_in *saddr_in, *daddr_in;

    saddr_in = (struct sockaddr_in *) saddr;
    daddr_in = (struct sockaddr_in *) daddr;

    if ((size_t) pkt_len < sizeof(*iph)) {
        E("ERROR: invalid packet length: %d", pkt_len);
        return -1;
    }

    iph = (struct iphdr *) pkt_data;
    iph_len = iph->ihl * 4;

    if ((size_t) iph_len < sizeof(*iph)) {
        E("ERROR: invalid IP header length: %d", iph_len);
        return -1;
    }

    if (iph->protocol != IPPROTO_TCP) {
        E("ERROR: not a TCP packet (protocol %d)", (int) iph->protocol);
        return -1;
    }

    if ((size_t) pkt_len < iph_len + sizeof(*tcph)) {
        E("ERROR: invalid packet length: %d", pkt_len);
        return -1;
    }

    tcph = (struct tcphdr *) ((uint8_t *) pkt_data + iph_len);
    tcph_len = tcph->doff * 4;
    if (pkt_len < iph_len + tcph_len) {
        E("ERROR: invalid packet length: %d", pkt_len);
        return -1;
    }

    memset(saddr_in, 0, sizeof(*saddr_in));
    saddr_in->sin_family = AF_INET;
    saddr_in->sin_addr.s_addr = iph->saddr;

    memset(daddr_in, 0, sizeof(*daddr_in));
    daddr_in->sin_family = AF_INET;
    daddr_in->sin_addr.s_addr = iph->daddr;

    *ttl = iph->ttl;
    *tcph_ptr = tcph;
    *tcp_payload_len = pkt_len - iph_len - tcph_len;

    return 0;
}

int fh_pkt4_make(uint8_t *buffer, size_t buffer_size, struct sockaddr *saddr,
                 struct sockaddr *daddr, uint8_t ttl, uint16_t sport_be,
                 uint16_t dport_be, uint32_t seq_be, uint32_t ackseq_be,
                 int psh, uint8_t *tcp_payload, size_t tcp_payload_size)
{
    size_t pkt_len;
    struct iphdr *iph;
    struct tcphdr *tcph;
    uint8_t *tcppl;
    struct sockaddr_in *saddr_in, *daddr_in;

    if (saddr->sa_family != AF_INET || daddr->sa_family != AF_INET) {
        E("ERROR: Invalid address family");
        return -1;
    }

    saddr_in = (struct sockaddr_in *) saddr;
    daddr_in = (struct sockaddr_in *) daddr;

    pkt_len = sizeof(*iph) + sizeof(*tcph) + tcp_payload_size;
    if (buffer_size < pkt_len + 1) {
        E("ERROR: %s", strerror(ENOBUFS));
        return -1;
    }

    iph = (struct iphdr *) buffer;
    tcph = (struct tcphdr *) (buffer + sizeof(*iph));
    tcppl = buffer + sizeof(*iph) + sizeof(*tcph);

    memset(iph, 0, sizeof(*iph));
    iph->version = 4;
    iph->ihl = sizeof(*iph) / 4;
    iph->tos = 0;
    iph->tot_len = htons(pkt_len);
    iph->id = ((rand() & 0xff) << 8) | (rand() & 0xff);
    iph->frag_off = htons(1 << 14 /* DF */);
    iph->ttl = ttl;
    iph->protocol = IPPROTO_TCP;
    iph->check = 0;
    iph->saddr = saddr_in->sin_addr.s_addr;
    iph->daddr = daddr_in->sin_addr.s_addr;

    memset(tcph, 0, sizeof(*tcph));
    tcph->source = sport_be;
    tcph->dest = dport_be;
    tcph->seq = seq_be;
    tcph->ack_seq = ackseq_be;
    tcph->doff = sizeof(*tcph) / 4;
    tcph->psh = psh;
    tcph->ack = 1;
    tcph->window = htons(0x0080);
    tcph->check = 0;
    tcph->urg_ptr = 0;

    if (tcp_payload_size) {
        memcpy(tcppl, tcp_payload, tcp_payload_size);
    }

    nfq_ip_set_checksum(iph);
    nfq_tcp_compute_checksum_ipv4(tcph, iph);

    return pkt_len;
}

static int hop_estimate(uint8_t ttl)
{
    if (ttl <= 64) {
        return 64 - ttl;
    } else if (ttl <= 128) {
        return 128 - ttl;
    } else {
        return 255 - ttl;
    }
}

static uint8_t calc_snd_ttl(int hops)
{
    int snd_ttl;

    if (!g_ctx.dynamic_pct) {
        return g_ctx.ttl;
    }

    snd_ttl = hops * g_ctx.dynamic_pct / 100;

    if (snd_ttl > g_ctx.ttl) {
        return snd_ttl;
    }

    return g_ctx.ttl;
}

static void ipaddr_to_str(struct sockaddr *addr, char ipstr[INET6_ADDRSTRLEN])
{
    static const char invalid[] = "INVALID";

    const char *res;

    if (addr->sa_family == AF_INET) {
        res = inet_ntop(AF_INET, &((struct sockaddr_in *) addr)->sin_addr,
                        ipstr, INET_ADDRSTRLEN);
        if (!res) {
            goto invalid;
        }
        return;
    } else if (addr->sa_family == AF_INET6) {
        res = inet_ntop(AF_INET6, &((struct sockaddr_in6 *) addr)->sin6_addr,
                        ipstr, INET6_ADDRSTRLEN);
        if (!res) {
            goto invalid;
        }
        return;
    }

invalid:
    memcpy(ipstr, invalid, sizeof(invalid));
}

static int remove_tfo_cookie(uint16_t ethertype, uint8_t *pkt,
                             struct tcphdr *tcph)
{
    int not_found = 0;
    size_t i = 0, tcpopt_len;
    uint8_t *tcpopt_data, kind, len;

    not_found = 1;
    tcpopt_len = tcph->doff * 4 - sizeof(*tcph);
    tcpopt_data = (uint8_t *) tcph + sizeof(*tcph);

    while (i < tcpopt_len) {
        kind = tcpopt_data[i];
        if (kind == 0 || kind == 1) {
            i++;
            continue;
        }

        if (i + 1 >= tcpopt_len) {
            break;
        }

        len = tcpopt_data[i + 1];

        if (len < 2 || i + len > tcpopt_len) {
            break;
        }

        if (kind == 34 /* TCP Fast Open Cookie */) {
            not_found = 0;
            memset(&tcpopt_data[i], 0x01 /* NOP */, len);
        }
        i += len;
    }

    if (!not_found) {
        if (ethertype == ETHERTYPE_IP) {
            nfq_tcp_compute_checksum_ipv4(tcph, (struct iphdr *) pkt);
        } else if (ethertype == ETHERTYPE_IPV6) {
            nfq_tcp_compute_checksum_ipv6(tcph, (struct ip6_hdr *) pkt);
        }
    }

    return not_found;
}

static int sendto_snat(struct sockaddr_ll *sll, struct sockaddr *daddr,
                       uint8_t *pkt_buff, int pkt_len)
{
    int res, ret, sock_fd;
    ssize_t nbytes;
    char *iface, iface_buf[IF_NAMESIZE];

    ret = -1;

    iface = if_indextoname(sll->sll_ifindex, iface_buf);
    if (!iface) {
        E("ERROR: if_indextoname(): %s", strerror(errno));
        return -1;
    }

    sock_fd = socket(daddr->sa_family, SOCK_RAW, IPPROTO_RAW);
    if (sock_fd < 0) {
        E("ERROR: socket(): %s", strerror(errno));
        return -1;
    }

    res = setsockopt(sock_fd, SOL_SOCKET, SO_BINDTODEVICE, iface,
                     strlen(iface));
    if (res < 0) {
        E("ERROR: setsockopt(): SO_BINDTODEVICE: %s", strerror(errno));
        goto close_socket;
    }

    res = setsockopt(sock_fd, SOL_SOCKET, SO_MARK, &g_ctx.fwmark,
                     sizeof(g_ctx.fwmark));
    if (res < 0) {
        E("ERROR: setsockopt(): SO_MARK: %s", strerror(errno));
        goto close_socket;
    }

    nbytes = sendto(sock_fd, pkt_buff, pkt_len, 0, daddr,
                    daddr->sa_family == AF_INET6 ? sizeof(struct sockaddr_in6)
                                                 : sizeof(struct sockaddr_in));
    if (nbytes < 0) {
        E("ERROR: sendto(): %s", strerror(errno));
        goto close_socket;
    }

    ret = nbytes;

close_socket:
    close(sock_fd);

    return ret;
}

static int send_payload(struct sockaddr_ll *sll, struct sockaddr *saddr,
                        struct sockaddr *daddr, uint8_t ttl, uint16_t sport_be,
                        uint16_t dport_be, uint32_t seq_be, uint32_t ackseq_be,
                        int need_snat)
{
    int pkt_len;
    ssize_t nbytes;
    uint8_t pkt_buff[1600] __attribute__((aligned));

    if (daddr->sa_family == AF_INET) {
        pkt_len = fh_pkt4_make(pkt_buff, sizeof(pkt_buff), saddr, daddr, ttl,
                               sport_be, dport_be, seq_be, ackseq_be, 1,
                               payload, payload_len);
        if (pkt_len < 0) {
            E(T(fh_pkt4_make));
            return -1;
        }
    } else if (daddr->sa_family == AF_INET6) {
        pkt_len = fh_pkt6_make(pkt_buff, sizeof(pkt_buff), saddr, daddr, ttl,
                               sport_be, dport_be, seq_be, ackseq_be, 1,
                               payload, payload_len);
        if (pkt_len < 0) {
            E(T(fh_pkt6_make));
            return -1;
        }
    } else {
        E("ERROR: Unknown address family: %d", (int) saddr->sa_family);
        return -1;
    }

    if (need_snat) {
        nbytes = sendto_snat(sll, daddr, pkt_buff, pkt_len);
        if (nbytes < 0) {
            E(T(sendto_snat));
            return -1;
        }
    } else {
        nbytes = sendto(sockfd, pkt_buff, pkt_len, 0, (struct sockaddr *) sll,
                        sizeof(*sll));
        if (nbytes < 0) {
            E("ERROR: sendto(): %s", strerror(errno));
            return -1;
        }
    }

    return 0;
}

int fh_rawsend_setup(void)
{
    int res, opt;
    const char *err_hint;

    sockfd = socket(AF_PACKET, SOCK_DGRAM, htons(ETH_P_ALL));
    if (sockfd < 0) {
        switch (errno) {
            case EPERM:
                err_hint = " (Are you root?)";
                break;
            default:
                err_hint = "";
        }
        E("ERROR: socket(): %s%s", strerror(errno), err_hint);
        return -1;
    }

    res = setsockopt(sockfd, SOL_SOCKET, SO_MARK, &g_ctx.fwmark,
                     sizeof(g_ctx.fwmark));
    if (res < 0) {
        E("ERROR: setsockopt(): SO_MARK: %s", strerror(errno));
        goto close_socket;
    }

    opt = 7;
    res = setsockopt(sockfd, SOL_SOCKET, SO_PRIORITY, &opt, sizeof(opt));
    if (res < 0) {
        E("ERROR: setsockopt(): SO_PRIORITY: %s", strerror(errno));
        goto close_socket;
    }

    /*
        Set SO_RCVBUF to the minimum, since we never call recvfrom() on this
        socket.
    */
    opt = 128;
    res = setsockopt(sockfd, SOL_SOCKET, SO_RCVBUF, &opt, sizeof(opt));
    if (res < 0) {
        E("ERROR: setsockopt(): SO_RCVBUF: %s", strerror(errno));
        goto close_socket;
    }

    return 0;

close_socket:
    close(sockfd);

    return -1;
}

void fh_rawsend_cleanup(void)
{
    if (sockfd >= 0) {
        close(sockfd);
        sockfd = -1;
    }
}

