		       const size_t n,
		       struct hc_slog_field *fields[]) {
  assert(s->write);
  s->write(s, n, fields);
}

void __hc_slog_write(struct hc_slog *s,
		     const size_t n,
		     struct hc_slog_field *fields[]) {
  slog_write(s, n, fields);
  
  for(size_t i = 0; i < n; i++) {
    struct hc_slog_field *f = fields[i];
    field_deinit(f);
    free(f);
  }
}

