#endif
}

JsonBuilder *apiResponse(char *message, bool success) {
    JsonBuilder *builder = jsonBuilder();
    jsonPutBool(builder, "success", success);
    jsonPutString(builder, "message", message);

    return builder;
}

HttpResponse apiSuccess() {
    JsonBuilder *json = apiResponse("Request was successful.", true);
    char *response = jsonStringify(json);
    freeJsonBuilder(json);

    return ok(response, APPLICATION_JSON);
}

HttpResponse apiFailure(char *message) {
    JsonBuilder *json = apiResponse(message, false);
    char *response = jsonStringify(json);
    freeJsonBuilder(json);

    return internalServerError(response, APPLICATION_JSON);
}

JsonBuilder *jsonBuilder() {
    JsonBuilder *builder = malloc(sizeof(JsonBuilder));

    if (!builder) {
        fprintf(stderr, "Fatal: out of memory\n");
        exit(EXIT_FAILURE);
    }

    builder->json = NULL;
    builder->jsonCount = 0;
    builder->jsonCapacity = 0;

    return builder;
}

JsonArray jsonArray() {
    return (JsonArray) {
        .items = NULL,
        .count = 0,
        .capacity = 0
    };
}

static void freeJson(Json json){
    if (json.type == JSON_STRING && json.value) {
        free(json.value);
    } else if (json.type == JSON_OBJECT && json.object) {
        freeJsonBuilder(json.object);
    } else if (json.type == JSON_ARRAY && json.array) {
        freeJsonArray(json.array);
    }

    if (json.key != NULL) {
        free(json.key);
    }
}

void freeJsonArray(JsonArray *jsonArray) {
    for (int i = 0; i < jsonArray->count; i++) {
        Json json = jsonArray->items[i];
        freeJson(json);
    }
    free(jsonArray->items);
}

void freeJsonBuilder(JsonBuilder *builder) {
    if (!builder) return;

    for (int i = 0; i < builder->jsonCount; i++) {
        Json json = builder->json[i];
        freeJson(json);
    }

    free(builder->json);

    builder->json = NULL;
    builder->jsonCount = 0;
    builder->jsonCapacity = 0;

    free(builder);
}

void addJson(JsonBuilder *builder, Json json) {
    if (builder->jsonCount >= builder->jsonCapacity) {
        builder->jsonCapacity = builder->jsonCapacity == 0 ? 1 : builder->jsonCapacity * 2;
        builder->json = realloc(builder->json, sizeof(Json) * builder->jsonCapacity);

        if (!builder->json) {
            fprintf(stderr, "Fatal: out of memory\n");
            exit(EXIT_FAILURE);
        }
    }
    builder->json[builder->jsonCount++] = json;
}

static Json makeJson(char *key, JsonType type) {
    Json json = (Json){
        .type = type,
        .key = strdup(key),
    };

    if (!json.key) {
        fprintf(stderr, "Fatal: out of memory\n");
        exit(EXIT_FAILURE);
    }

    return json;
}

static void gettimeofday (struct timeval *tv, void *dummy)
{
	FILETIME	ftime;
	uint64_t	n;

	GetSystemTimeAsFileTime (&ftime);
	n = (((uint64_t) ftime.dwHighDateTime << 32)
	     + (uint64_t) ftime.dwLowDateTime);
	if (n) {
		n /= 10;
		n -= ((369 * 365 + 89) * (uint64_t) 86400) * 1000000;
	}

	tv->tv_sec = n / 1000000;
	tv->tv_usec = n % 1000000;
}

