static inline uint32_t get_unaligned_le32(const uint8_t *buf)
{
    return (uint32_t)buf[0]
            | ((uint32_t)buf[1] << 8)
            | ((uint32_t)buf[2] << 16)
            | ((uint32_t)buf[3] << 24);
}

static inline uint32_t get_unaligned_be32(const uint8_t *buf)
{
    return (uint32_t)(buf[0] << 24)
            | ((uint32_t)buf[1] << 16)
            | ((uint32_t)buf[2] << 8)
            | (uint32_t)buf[3];
}

static inline void put_unaligned_le32(uint32_t val, uint8_t *buf)
{
    buf[0] = (uint8_t)val;
    buf[1] = (uint8_t)(val >> 8);
    buf[2] = (uint8_t)(val >> 16);
    buf[3] = (uint8_t)(val >> 24);
}

static inline void put_unaligned_be32(uint32_t val, uint8_t *buf)
{
    buf[0] = (uint8_t)(val >> 24);
    buf[1] = (uint8_t)(val >> 16);
    buf[2] = (uint8_t)(val >> 8);
    buf[3] = (uint8_t)val;
}

static inline void lzma_state_literal(enum lzma_state *state)
{
    if (*state <= STATE_SHORTREP_LIT_LIT)
        *state = STATE_LIT_LIT;
    else if (*state <= STATE_LIT_SHORTREP)
        *state -= 3;
    else
        *state -= 6;
}

static inline void lzma_state_match(enum lzma_state *state)
{
    *state = *state < LIT_STATES ? STATE_LIT_MATCH : STATE_NONLIT_MATCH;
}

static inline void lzma_state_long_rep(enum lzma_state *state)
{
    *state = *state < LIT_STATES ? STATE_LIT_LONGREP : STATE_NONLIT_REP;
}

static inline void lzma_state_short_rep(enum lzma_state *state)
{
    *state = *state < LIT_STATES ? STATE_LIT_SHORTREP : STATE_NONLIT_REP;
}

static inline uint32_t lzma_get_dist_state(uint32_t len)
{
    return len < DIST_STATES + MATCH_LEN_MIN
            ? len - MATCH_LEN_MIN : DIST_STATES - 1;
}

static void prv_enable_chip_select(void) {
  //GPIO_WriteBit(DISP_GPIO, DISP_PIN_SCS, Bit_SET);
  BOARD_DISP_CS_PORT->OUTSET = (1 << BOARD_DISP_CS_PIN);
  // required setup time > 3us
  NRFX_DELAY_US(7);
}

static void prv_disable_chip_select(void) {
  // delay while last byte is emitted by the SPI peripheral
  NRFX_DELAY_US(7);

  //GPIO_WriteBit(DISP_GPIO, DISP_PIN_SCS, Bit_RESET);
  BOARD_DISP_CS_PORT->OUTCLR = (1 << BOARD_DISP_CS_PIN);
  // hold time > 1us
  // produce a delay 4ms
  NRFX_DELAY_US(4);
}

static void prv_enable_display_access(void) {
  prv_enable_chip_select();
}

static void prv_disable_display_access(void) {
  prv_disable_chip_select();
}

static void prv_display_write_byte(uint8_t d) {
  nrfx_spim_xfer_desc_t desc = NRFX_SPIM_XFER_TX(&d, 1);
  nrfx_spim_xfer(&spim, &desc, 0);
  // Block until the tx buffer is empty
  //SPI_I2S_SendData(DISP_SPI, d);
  //while (!SPI_I2S_GetFlagStatus(DISP_SPI, SPI_I2S_FLAG_TXE)) {}
}

static void prv_display_start(void) {
  // Hold LCD on
  // GPIO_WriteBit(DISP_LCD_GPIO, DISP_PIN_LCD, Bit_SET);
  BOARD_DISP_DISP_PORT->OUTSET = (1 << BOARD_DISP_DISP_PIN);
}

void display_clear(void) {
  prv_enable_display_access();

  prv_display_write_byte(DISP_MODE_CLEAR);
  prv_display_write_byte(0x00);

  prv_disable_display_access();
}

static void prv_display_enter_static(void) {
  prv_enable_display_access();

  prv_display_write_byte(DISP_MODE_STATIC);
  prv_display_write_byte(0x00);
  prv_display_write_byte(0x00);

  prv_disable_display_access();
}

static uint8_t prv_reverse_bits(uint8_t input) {
  uint8_t result;
  __asm__ ("rev  %[result], %[input]\n\t"
           "rbit %[result], %[result]"
           : [result] "=r" (result)
           : [input] "r" (input));
  return result;
}

static void prv_display_start_write(void) {
  prv_enable_display_access();

  prv_display_write_byte(DISP_MODE_WRITE);
}

static char* trim_whitespace(char* str) {
    char* end;
    // Trim leading space
    while (*str == ' ' || *str == '\t' || *str == '\r' || *str == '\n') str++;
    if (*str == 0) return str;
    // Trim trailing space
    end = str + strlen(str) - 1;
    while (end > str && (*end == ' ' || *end == '\t' || *end == '\r' || *end == '\n')) end--;
    *(end + 1) = '\0';
    return str;
}

Config* parse_config(const char* filename) {
    FILE* file = fopen(filename, "r");
    if (!file) return NULL;

    Config* config = (Config*)malloc(sizeof(Config));
    if (!config) {
        fclose(file);
        return NULL;
    }
    config->count = 0;
    config->capacity = INITIAL_CAPACITY;
    config->items = (ConfigItem*)malloc(sizeof(ConfigItem) * config->capacity);
    if (!config->items) {
        free(config);
        fclose(file);
        return NULL;
    }

    char line[1024];
    while (fgets(line, sizeof(line), file)) {
        char* equal_sign = strchr(line, '=');
        if (!equal_sign) continue;  // Skip lines without '='
        *equal_sign = '\0';
        char* key = trim_whitespace(line);
        char* value = trim_whitespace(equal_sign + 1);
        // Remove trailing newline from value
        size_t vlen = strlen(value);
        if (vlen > 0 && (value[vlen - 1] == '\n' || value[vlen - 1] == '\r')) {
            value[vlen - 1] = '\0';
        }
        // Expand capacity if needed
        if (config->count >= config->capacity) {
            size_t new_capacity = config->capacity * 2;
            ConfigItem* new_items = (ConfigItem*)realloc(config->items, sizeof(ConfigItem) * new_capacity);
            if (!new_items) break;
            config->items = new_items;
            config->capacity = new_capacity;
        }
        config->items[config->count].key = strdup(key);
        config->items[config->count].value = strdup(value);
        config->count++;
    }
    fclose(file);
    return config;
}

const char* get_config_value(const Config* config, const char* key) {
    if (!config || !key) return NULL;
    for (size_t i = 0; i < config->count; ++i) {
        if (strcmp(config->items[i].key, key) == 0) {
            return config->items[i].value;
        }
    }
    return NULL;
}

void free_config(Config* config) {
    if (!config) return;
    for (size_t i = 0; i < config->count; ++i) {
        free(config->items[i].key);
        free(config->items[i].value);
    }
    free(config->items);
    free(config);
}

void windows_attach_or_alloc_console() {
    if (IsWindows() && config_win_gui && !attach_console) {
        attach_console = 1;
        if (!AttachConsole(kNtAttachParentProcess)) {
            alloc_console = 1;
            AllocConsole();
        }
        freopen("CONOUT$", "w", stdout);
        freopen("CONOUT$", "w", stderr);
    }
}

void console_log(const char *format, ...) {
    windows_attach_or_alloc_console();
    va_list args;
    va_start(args, format);
    vprintf(format, args);
    va_end(args);
}

void close_console() {
    attach_console = 0;
    alloc_console = 0;
    fclose(stdout);
    fclose(stderr);
    FreeConsole();
}

void exit_with_message(const char *format, ...) {
    config_win_gui = 1;
    windows_attach_or_alloc_console();
    va_list args;
    va_start(args, format);
    vprintf(format, args);
    va_end(args);
    printf("\nPress Enter to exit...\n");
    freopen("CONIN$", "r", stdin);
    getchar();
    exit(1);
}

int path_exists(const char *filename) {
    return access(filename, F_OK) == 0;
}

char *get_executable_dir() {
    char *executable_path = strdup(GetProgramExecutableName());
    char *last_slash = strrchr(executable_path, '/');
    *(last_slash + 1) = '\0';
    return executable_path;
}

static inline char *getTabs(AoStr *str) {
    switch (str->len) {
        case 2: return "\t\t";
        case 3: return "\t\t";
        case 4: return "\t";
        default: return "\t";
    }
}

void prsAsmMem(Cctrl *cc, AoStr *buf) {
    Lexeme *tok;
    tok = cctrlAsmTokenGet(cc);
    if (tok->tk_type != TK_IDENT) {
        cctrlRaiseException(cc,"[<register>] expected got: %s",lexemeToString(tok));
    }
    cctrlTokenExpect(cc,']');
    aoStrCatFmt(buf,"(%.*s)",tok->len,tok->start);
    aoStrToLowerCase(buf);
}

void prsAsmOffset(Cctrl *cc, AoStr *buf, Lexeme *tok) {
    if (tok->tk_type != TK_I64) {
        cctrlRaiseException(cc,"Expected TK_I64 type got: %s",lexemeToString(tok));
    }

    cctrlTokenExpect(cc,'[');
    tok = cctrlAsmTokenGet(cc);
    if (tok->tk_type != TK_IDENT) {
        cctrlRaiseException(cc,"Expected <number>[<register>] Got: %s",
                lexemeToString(tok));
    }
    cctrlTokenExpect(cc,']');
    aoStrCatFmt(buf, "(%.*s)",tok->len,tok->start);
}

void prsAsmImm(Cctrl *cc, AoStr *buf, Lexeme *tok) {
    Lexeme *next;
    switch (tok->tk_type) {
        case TK_PUNCT:
            if (tok->i64 != '-') {
                cctrlRaiseException(cc,"Expected '-'<numerical>");
            }

            tok = cctrlAsmTokenGet(cc);
            if (tok->tk_type != TK_I64 && tok->tk_type != TK_F64) {
                cctrlRaiseException(cc,"Expected -<numerical> got: %s\n",
                        lexemeToString(tok));
            }
            next = cctrlTokenPeek(cc);
            if (!tokenPunctIs(next,'[')) {
                aoStrPutChar(buf,'$');
                aoStrCatPrintf(buf, "-%zu",(unsigned long)tok->i64);
            } else {
                aoStrCatPrintf(buf, "-%zu",(unsigned long)tok->i64);
                cctrlAsmTokenGet(cc);
                prsAsmMem(cc,buf);
            }
            break;

        case TK_CHAR_CONST:
        case TK_I64:
            next = cctrlTokenPeek(cc);
            if (!tokenPunctIs(next,'[')) {
                aoStrPutChar(buf,'$');
                if (tok->ishex) {
                    aoStrCatPrintf(buf, "%#llX",(size_t)tok->i64);
                } else { 
                    aoStrCatPrintf(buf, "%zu",(size_t)tok->i64);
                }
            } else {
                if (tok->ishex) {
                    aoStrCatPrintf(buf, "%#llX",(size_t)tok->i64);
                } else { 
                    aoStrCatPrintf(buf, "%zu",(size_t)tok->i64);
                }
                if (tokenPunctIs(next,'[')) {
                    cctrlAsmTokenGet(cc);
                    prsAsmMem(cc,buf);
                }
            }
            break;
        default:
            printf("mem parse: %s\n", lexemeToString(tok));
            break;
    }
}

void prsAsmLabel(Cctrl *cc, AoStr *buf) {
    Lexeme *tok = cctrlAsmTokenGet(cc);
    if (!tokenPunctIs(tok,'@')) {
        cctrlRaiseException(cc,": Labels must be: '@@<int>'");
    }

    tok = cctrlAsmTokenGet(cc);
    if (tok->tk_type != TK_I64) {
        cctrlRaiseException(cc,": Labels must be: '@@<int>'");
    }

    s64 label_num = tok->i64;
    Lexeme *next = cctrlTokenPeek(cc);
    AoStr *label = aoStrDup(cc->tmp_asm_fname);
    aoStrToLowerCase(label);
    if (tokenPunctIs(next,':')) {
        aoStrCatFmt(buf, ".%S_%U:",label,label_num);
        cctrlAsmTokenGet(cc);
    } else {
        aoStrCatFmt(buf, ".%S_%U",label,label_num);
    }
    aoStrRelease(label);
}

void prsAsmPunct(Cctrl *cc, Lexeme *tok, AoStr *buf) {
    switch (tok->i64) {
        case '[':
            prsAsmMem(cc,buf);
            break;
        case '-':
            prsAsmImm(cc,buf,tok);
            break;
        case '@':
            prsAsmLabel(cc,buf);
            break;
        default:
            lexemePrint(tok);
            cctrlRaiseException(cc,": Unexpected character");
    }

    Lexeme *next = cctrlTokenPeek(cc);
    if (tokenPunctIs(next,'[')) {
        cctrlTokenRewind(cc);
        tok = cctrlAsmTokenGet(cc);
        prsAsmOffset(cc,buf,tok);
    }
}

Ast *prsAsmToATT(Cctrl *cc, int parse_one) {
    AoStr *op1 = NULL, *op2 = NULL, *op3 = NULL, *asm_code = NULL, *curblock = NULL, *stdfunc = NULL, *curfunc = NULL;
    List *asm_functions;
    Ast *asm_function, *asm_block;
    Lexeme *tok, *next;
    int isbol = 0, count = 0;

    asm_functions = listNew();
    asm_code = aoStrNew();
    curblock = parse_one ? asm_code : NULL;
    memset(asm_code->data,'\0',asm_code->capacity-1);

    cctrlTokenExpect(cc, '{');
    tok = cctrlAsmTokenGet(cc);

    while (!tokenPunctIs(tok, '}')) {
        switch (tok->tk_type) {
            case TK_CHAR_CONST:
            case TK_I64: {
                switch (count) {
                    case 1:
                        count++;
                        op2 = aoStrNew();
                        prsAsmImm(cc,op2,tok);
                        break;
                    case 2:
                        count++;
                        op3 = aoStrNew();
                        prsAsmImm(cc,op3,tok);
                        break;
                }
                break;
            }

            case TK_KEYWORD: {
                if (tok->i64 == KW_SIZEOF) {
                    Ast *sizeof_ast = parseSizeof(cc);
                    u64 size = (unsigned long)sizeof_ast->i64;
                    switch (count) {
                        case 1:
                            count++;
                            op2 = aoStrPrintf("$%zu",size);
                            break;
                        case 2:
                            count++;
                            op3 = aoStrPrintf("$%zu",size);
                            break;
                    }
                } else {
                    cctrlRaiseException(cc, "\nCannot Handle keyword: %.*s in this context", tok->len, tok->start);
                }
                break;
            }    


            case TK_IDENT: {
                next = cctrlTokenPeek(cc);
                if (tokenPunctIs(next, TK_DBL_COLON) || tokenPunctIs(next,':')) {
                    cctrlAsmTokenGet(cc);
                    cctrlTokenExpect(cc, '\n');

                    if (curblock == NULL) {
                        curblock = aoStrNew();
                    } else {
                        /* Save the current function */
                        aoStrCatLen(asm_code,curfunc->data,curfunc->len);
                        aoStrCatLen(asm_code,":\n",2);
                        aoStrCatLen(asm_code,curblock->data,curblock->len);
                        aoStrPutChar(asm_code,'\n');
                        /* Create an ast */
                        asm_function = astAsmFunctionDef(curfunc,curblock);
                        listAppend(asm_functions,asm_function);
                        if (!mapAddOrErr(cc->asm_functions, curfunc->data, asm_function)) {
                            cctrlIce(cc, "Already defined assembly function: %s", curfunc->data);
                        }
                        curblock = aoStrNew();
                    }

                    /* Just the function name in op1, this is so it can be 
                     * called in the c code. */
                    curfunc = aoStrDupRaw(tok->start,tok->len);
                    /* Save the name for pasting labels */
                    cc->tmp_asm_fname = curfunc;
                    tok = cctrlAsmTokenGet(cc);
                    isbol = 1;
                    continue;
                } 

                else if (!isbol && count != 1 && tokenPunctIs(next, '[')) {
                    /* Possibly loading a global */
                    op3 = aoStrDupRaw(tok->start,tok->len);
                    cctrlAsmTokenGet(cc);
                    next = cctrlAsmTokenGet(cc);
                    aoStrCatFmt(op3, "(%.*s)",next->len, next->start);
                    cctrlAsmTokenGet(cc);
                } else
                if (isbol) {
                    op1 = aoStrDupRaw(tok->start,tok->len);
                    isbol = 0;
                } else {
                    if (count == 1) {
                        op2 = aoStrDupRaw(tok->start,tok->len);
                    } else {
                        op3 = aoStrDupRaw(tok->start,tok->len);
                    }
                }
                count++;
                break;
            }

            case TK_PUNCT: {
                switch (tok->i64) {
                    case '\n':
                        switch (count) {
                            case 0:
                                break;

                            case 1:
                                /* Not A jump */
                                if (op1->data[0] != '.') { 
                                    aoStrPutChar(curblock,'\t');
                                }
                                /* Only a few functions get called as one 
                                 * operation */
                                aoStrToLowerCase(op1);
                                if (setHasLen(cc->libc_functions, op1->data,op1->len)) {
                                    stdfunc = astNormaliseFunctionName(op1->data);
                                    aoStrCatFmt(curblock,"%S\n",stdfunc);
                                    aoStrRelease(stdfunc);
                                } else {
                                    aoStrCatFmt(curblock,"%S\n",op1);
                                }
                                aoStrRelease(op1);
                                break;

                            case 2: {
                                aoStrToLowerCase(op1);
                                aoStrCatPrintf(curblock,"\t%s%s",op1->data,getTabs(op1));
                                int is_call = op1->len == 4 && !strncasecmp(op1->data,str_lit("call"));

                                if (is_call) {
                                    if (mapGetLen(cc->global_env, op2->data, op2->len) != NULL || 
                                        setHasLen(cc->libc_functions, op2->data, op2->len)) {
                                        stdfunc = astNormaliseFunctionName(op2->data);
                                        aoStrCatFmt(curblock,"%S\n",stdfunc);
                                        aoStrRelease(stdfunc);
                                    } else {
                                        if (op2->data[0] == '%') {
                                            aoStrPutChar(curblock,'*');
                                        }
                                        aoStrCatFmt(curblock,"%S\n",op2);
                                    }
                                } else {
                                  int is_jump = op1->len == 3 && 
                                                !strncasecmp(op1->data,str_lit("jmp"));
                                    if (is_jump && op2->data[0] == '%') {
                                        aoStrPutChar(curblock,'*');
                                    }
                                    aoStrToLowerCase(op2);
                                    aoStrCatFmt(curblock,"%S\n",op2);
                                }
                                aoStrRelease(op1);
                                aoStrRelease(op2);
                                break;
                            }

                            case 3:
                                aoStrToLowerCase(op1);

                                aoStrCatFmt(curblock,"\t%S%s", op1,getTabs(op1));

                                aoStrCatFmt(curblock,"%S, %S\n",op3, op2);

                                aoStrRelease(op1);
                                aoStrRelease(op2);
                                aoStrRelease(op3);
                                break;
                            default:
                                cctrlRaiseException(cc,"Unexpected number of arguments for"
                                        " x86 transpilation: %d %s %s",
                                        count,op1->data,op2->data);
                        }
                        isbol = 1;
                        count = 0;
                        break;

                    case ',':
                        break;
                    default:
                        switch (count) {
                            case 0:
                                op1 = aoStrNew();
                                prsAsmPunct(cc,tok,op1);
                                break;
                            case 1:
                                op2 = aoStrNew();
                                prsAsmPunct(cc,tok,op2);
                                break;
                            case 2:
                                op3 = aoStrNew();
                                prsAsmPunct(cc,tok,op3);
                                break;
                        }
                        count++;
                        break;
                }
                break;
            }

        }
        tok = cctrlAsmTokenGet(cc);
    }

    if (curfunc) {
        aoStrCatLen(asm_code,curfunc->data,curfunc->len);
        aoStrCatLen(asm_code,":\n",2);
        aoStrCatLen(asm_code,curblock->data,curblock->len);
        asm_function = astAsmFunctionDef(curfunc,curblock);
        listAppend(asm_functions,asm_function);
        if (!mapAddOrErr(cc->asm_functions, curfunc->data, asm_function)) {
            cctrlIce(cc, "Already defined assembly function: %s", curfunc->data);
        }
    }
    asm_block = astAsmBlock(asm_code,asm_functions);
    return asm_block;
}

Ast *prsAsm(Cctrl *cc, int parse_one) {
    return prsAsmToATT(cc, parse_one);
}

char *readfile(char *path) {
    int fd;
    if ((fd = open(path, O_RDONLY, 0644)) == -1) {
        loggerPanic("Failed to open file\n");
    }

    int len = lseek(fd, 0, SEEK_END);
    lseek(fd, 0, SEEK_SET);

    char *buf = (char *)malloc(sizeof(char) * len);
    if (read(fd, buf, len) != len) {
        loggerPanic("Failed to read whole file\n");
    }
    buf[len] = '\0';
    close(fd);
    return buf;
}

u8 irOpIsCmp(IrOp opcode) {
    if (opcode == IR_ICMP || opcode == IR_FCMP) {
        return 1;
    }
    return 0;
}

local int inflateStateCheck(strm)
z_streamp strm;
{
    struct inflate_state FAR *state;
    if (strm == Z_NULL ||
        strm->zalloc == (alloc_func)0 || strm->zfree == (free_func)0)
        return 1;
    state = (struct inflate_state FAR *)strm->state;
    if (state == Z_NULL || state->strm != strm ||
        state->mode < HEAD || state->mode > SYNC)
        return 1;
    return 0;
}

int ZEXPORT inflateResetKeep(strm)
z_streamp strm;
{
    struct inflate_state FAR *state;

    if (inflateStateCheck(strm)) return Z_STREAM_ERROR;
    state = (struct inflate_state FAR *)strm->state;
    strm->total_in = strm->total_out = state->total = 0;
    strm->msg = Z_NULL;
    if (state->wrap)        /* to support ill-conceived Java test suite */
        strm->adler = state->wrap & 1;
    state->mode = HEAD;
    state->last = 0;
    state->havedict = 0;
    state->dmax = 32768U;
    state->head = Z_NULL;
    state->hold = 0;
    state->bits = 0;
    state->lencode = state->distcode = state->next = state->codes;
    state->sane = 1;
    state->back = -1;
    Tracev((stderr, "inflate: reset\n"));
    return Z_OK;
}

int ZEXPORT inflateReset(strm)
z_streamp strm;
{
    struct inflate_state FAR *state;

    if (inflateStateCheck(strm)) return Z_STREAM_ERROR;
    state = (struct inflate_state FAR *)strm->state;
    state->wsize = 0;
    state->whave = 0;
    state->wnext = 0;
    return inflateResetKeep(strm);
}

int ZEXPORT inflateReset2(strm, windowBits)
z_streamp strm;
int windowBits;
{
    int wrap;
    struct inflate_state FAR *state;

    /* get the state */
    if (inflateStateCheck(strm)) return Z_STREAM_ERROR;
    state = (struct inflate_state FAR *)strm->state;

    /* extract wrap request from windowBits parameter */
    if (windowBits < 0) {
        wrap = 0;
        windowBits = -windowBits;
    }
    else {
        wrap = (windowBits >> 4) + 5;
#ifdef GUNZIP
        if (windowBits < 48)
            windowBits &= 15;
#endif
    }

    /* set number of window bits, free window if different */
    if (windowBits && (windowBits < 8 || windowBits > 15))
        return Z_STREAM_ERROR;
    if (state->window != Z_NULL && state->wbits != (unsigned)windowBits) {
        ZFREE(strm, state->window);
        state->window = Z_NULL;
    }

    /* update state and reset the rest of it */
    state->wrap = wrap;
    state->wbits = (unsigned)windowBits;
    return inflateReset(strm);
}

int ZEXPORT inflateInit2_(strm, windowBits, version, stream_size)
z_streamp strm;
int windowBits;
const char *version;
int stream_size;
{
    int ret;
    struct inflate_state FAR *state;

    if (version == Z_NULL || version[0] != ZLIB_VERSION[0] ||
        stream_size != (int)(sizeof(z_stream)))
        return Z_VERSION_ERROR;
    if (strm == Z_NULL) return Z_STREAM_ERROR;
    strm->msg = Z_NULL;                 /* in case we return an error */
    if (strm->zalloc == (alloc_func)0) {
#ifdef Z_SOLO
        return Z_STREAM_ERROR;
#else
        strm->zalloc = zcalloc;
        strm->opaque = (voidpf)0;
#endif
    }
    if (strm->zfree == (free_func)0)
#ifdef Z_SOLO
        return Z_STREAM_ERROR;
#else
        strm->zfree = zcfree;
#endif
    state = (struct inflate_state FAR *)
            ZALLOC(strm, 1, sizeof(struct inflate_state));
    if (state == Z_NULL) return Z_MEM_ERROR;
    Tracev((stderr, "inflate: allocated\n"));
    strm->state = (struct internal_state FAR *)state;
    state->strm = strm;
    state->window = Z_NULL;
    state->mode = HEAD;     /* to pass state test in inflateReset2() */
    ret = inflateReset2(strm, windowBits);
    if (ret != Z_OK) {
        ZFREE(strm, state);
        strm->state = Z_NULL;
    }
    return ret;
}

int ZEXPORT inflateInit_(strm, version, stream_size)
z_streamp strm;
const char *version;
int stream_size;
{
    return inflateInit2_(strm, DEF_WBITS, version, stream_size);
}

int ZEXPORT inflatePrime(strm, bits, value)
z_streamp strm;
int bits;
int value;
{
    struct inflate_state FAR *state;

    if (inflateStateCheck(strm)) return Z_STREAM_ERROR;
    state = (struct inflate_state FAR *)strm->state;
    if (bits < 0) {
        state->hold = 0;
        state->bits = 0;
        return Z_OK;
    }
    if (bits > 16 || state->bits + (uInt)bits > 32) return Z_STREAM_ERROR;
    value &= (1L << bits) - 1;
    state->hold += (unsigned)value << state->bits;
    state->bits += (uInt)bits;
    return Z_OK;
}

local void fixedtables(state)
struct inflate_state FAR *state;
{
#ifdef BUILDFIXED
    static int virgin = 1;
    static code *lenfix, *distfix;
    static code fixed[544];

    /* build fixed huffman tables if first call (may not be thread safe) */
    if (virgin) {
        unsigned sym, bits;
        static code *next;

        /* literal/length table */
        sym = 0;
        while (sym < 144) state->lens[sym++] = 8;
        while (sym < 256) state->lens[sym++] = 9;
        while (sym < 280) state->lens[sym++] = 7;
        while (sym < 288) state->lens[sym++] = 8;
        next = fixed;
        lenfix = next;
        bits = 9;
        inflate_table(LENS, state->lens, 288, &(next), &(bits), state->work);

        /* distance table */
        sym = 0;
        while (sym < 32) state->lens[sym++] = 5;
        distfix = next;
        bits = 5;
        inflate_table(DISTS, state->lens, 32, &(next), &(bits), state->work);

        /* do this just once */
        virgin = 0;
    }
#else /* !BUILDFIXED */
#   include "inffixed.h"
#endif /* BUILDFIXED */
    state->lencode = lenfix;
    state->lenbits = 9;
    state->distcode = distfix;
    state->distbits = 5;
}

void makefixed()
{
    unsigned low, size;
    struct inflate_state state;

    fixedtables(&state);
    puts("    /* inffixed.h -- table for decoding fixed codes");
    puts("     * Generated automatically by makefixed().");
    puts("     */");
    puts("");
    puts("    /* WARNING: this file should *not* be used by applications.");
    puts("       It is part of the implementation of this library and is");
    puts("       subject to change. Applications should only use zlib.h.");
    puts("     */");
    puts("");
    size = 1U << 9;
    printf("    static const code lenfix[%u] = {", size);
    low = 0;
    for (;;) {
        if ((low % 7) == 0) printf("\n        ");
        printf("{%u,%u,%d}", (low & 127) == 99 ? 64 : state.lencode[low].op,
               state.lencode[low].bits, state.lencode[low].val);
        if (++low == size) break;
        putchar(',');
    }
    puts("\n    };");
    size = 1U << 5;
    printf("\n    static const code distfix[%u] = {", size);
    low = 0;
    for (;;) {
        if ((low % 6) == 0) printf("\n        ");
        printf("{%u,%u,%d}", state.distcode[low].op, state.distcode[low].bits,
               state.distcode[low].val);
        if (++low == size) break;
        putchar(',');
    }
    puts("\n    };");
}

local int updatewindow(strm, end, copy)
z_streamp strm;
const Bytef *end;
unsigned copy;
{
    struct inflate_state FAR *state;
    unsigned dist;

    state = (struct inflate_state FAR *)strm->state;

    /* if it hasn't been done already, allocate space for the window */
    if (state->window == Z_NULL) {
        state->window = (unsigned char FAR *)
                        ZALLOC(strm, 1U << state->wbits,
                               sizeof(unsigned char));
        if (state->window == Z_NULL) return 1;
    }

    /* if window not in use yet, initialize */
    if (state->wsize == 0) {
        state->wsize = 1U << state->wbits;
        state->wnext = 0;
        state->whave = 0;
    }

    /* copy state->wsize or less output bytes into the circular window */
    if (copy >= state->wsize) {
        zmemcpy(state->window, end - state->wsize, state->wsize);
        state->wnext = 0;
        state->whave = state->wsize;
    }
    else {
        dist = state->wsize - state->wnext;
        if (dist > copy) dist = copy;
        zmemcpy(state->window + state->wnext, end - copy, dist);
        copy -= dist;
        if (copy) {
            zmemcpy(state->window, end - copy, copy);
            state->wnext = copy;
            state->whave = state->wsize;
        }
        else {
            state->wnext += dist;
            if (state->wnext == state->wsize) state->wnext = 0;
            if (state->whave < state->wsize) state->whave += dist;
        }
    }
    return 0;
}

esp_err_t dsps_biquad_gen_lpf_f32(float *coeffs, float f, float qFactor)
{
    if (qFactor <= 0.0001) {
        qFactor = 0.0001;
    }
    float Fs = 1;

    float w0 = 2 * M_PI * f / Fs;
