char *strstr(const char *haystack, const char *needle)
{
	return (char *)memmem(haystack, strlen(haystack), needle,
			      strlen(needle));
}

static char *strchrnul(const char *s, int c)
{
    while (true) {
        char chr = *s;
        if (chr == c || chr == 0) break;
        s++;
    }
    return (char *) s;
}

static char to_lower(char chr) {
    if (chr >= 'A' && chr <= 'Z') return chr | 0x20;
    return chr;
}

static int strnicmp(const char* str1, const char* str2, size_t len) {
    do {
        int ret = to_lower(*str1) - to_lower(*str2);
        if (ret != 0) return ret;
        if (*str1 == 0) break;
        str1++;
        str2++;
    } while (--len != 0);

    return 0;
}

static inline uint16_t fsectoff(l9660_file *f)
{
    return f->position % 2048;
}

static inline uint32_t fsector(l9660_file *f)
{
    return f->position / 2048;
}

static inline uint32_t fnextsectpos(l9660_file *f)
{
    return (f->position + 2047) & ~2047;
}

l9660_status l9660_openfs(
    l9660_fs *fs,
    bool (*read_sector)(l9660_fs *fs, void *buf, uint32_t sector))
{
    fs->read_sector = read_sector;

#ifndef L9660_SINGLEBUFFER
    l9660_vdesc_primary *pvd = PVD(&fs->pvd);
#else
    last_file = NULL;
    l9660_vdesc_primary *pvd = PVD(gbuf);
#endif
    uint32_t idx = 0x10;
    for (;;) {
        // Read next sector
        if (!read_sector(fs, pvd, idx))
            return L9660_EIO;

        // Validate magic
        if (memcmp(pvd->hdr.magic, "CD001", 5) != 0)
            return L9660_EBADFS;

        if (pvd->hdr.type == 1)
            break; // Found PVD
        else if(pvd->hdr.type == 255)
            return L9660_EBADFS;
    }

#ifdef L9660_SINGLEBUFFER
    memcpy(&fs->root_dir_ent, &pvd->root_dir_ent, pvd->root_dir_ent.length);
#endif

    return L9660_OK;
}

l9660_status l9660_fs_open_root(l9660_dir *dir, l9660_fs *fs)
{
    l9660_file *f = &dir->file;
#ifndef L9660_SINGLEBUFFER
    l9660_dirent *dirent = &PVD(&fs->pvd)->root_dir_ent;
#else
    l9660_dirent *dirent = &fs->root_dir_ent;
#endif

    f->fs = fs;
    f->first_sector = READ32(dirent->sector);
    f->length       = READ32(dirent->size);
    f->position     = 0;

    return L9660_OK;
}

static l9660_status buffer(l9660_file *f)
{
#ifdef L9660_SINGLEBUFFER
    last_file = f;
#endif
    if (!f->fs->read_sector(f->fs, BUF(f), f->first_sector + f->position / 2048))
        return L9660_EIO;
    else
        return L9660_OK;
}

cb_ret_t
button_default_callback (Widget *w, Widget *sender, widget_msg_t msg, int parm, void *data)
{
    WButton *b = BUTTON (w);
    WGroup *g = w->owner;
    WDialog *h = DIALOG (g);
    int off = 0;

    switch (msg)
    {
    case MSG_HOTKEY:
        /*
         * Don't let the default button steal Enter from the current
         * button.  This is a workaround for the flawed event model
         * when hotkeys are sent to all widgets before the key is
         * handled by the current widget.
         */
        if (parm == '\n' && WIDGET (g->current->data) == w)
        {
            send_message (w, sender, MSG_KEY, ' ', data);
            return MSG_HANDLED;
        }

        if (parm == '\n' && b->flags == DEFPUSH_BUTTON)
        {
            send_message (w, sender, MSG_KEY, ' ', data);
            return MSG_HANDLED;
        }

        if (b->text.hotkey != NULL && g_ascii_tolower ((gchar) b->text.hotkey[0]) == parm)
        {
            send_message (w, sender, MSG_KEY, ' ', data);
            return MSG_HANDLED;
        }
        return MSG_NOT_HANDLED;

    case MSG_KEY:
        if (parm != ' ' && parm != '\n')
            return MSG_NOT_HANDLED;

        h->ret_value = b->action;
        if (b->callback == NULL || b->callback (b, b->action) != 0)
            dlg_close (h);

        return MSG_HANDLED;

    case MSG_CURSOR:
        switch (b->flags)
        {
        case DEFPUSH_BUTTON:
            off = 3;
            break;
        case NORMAL_BUTTON:
            off = 2;
            break;
        case NARROW_BUTTON:
            off = 1;
            break;
        case HIDDEN_BUTTON:
        default:
            off = 0;
            break;
        }
        widget_gotoyx (w, 0, b->hotpos + off);
        return MSG_HANDLED;

    case MSG_DRAW:
    {
        gboolean focused;

        focused = widget_get_state (w, WST_FOCUSED);

        widget_selectcolor (w, focused, FALSE);
        widget_gotoyx (w, 0, 0);

        switch (b->flags)
        {
        case DEFPUSH_BUTTON:
            tty_print_string ("[< ");
            break;
        case NORMAL_BUTTON:
            tty_print_string ("[ ");
            break;
        case NARROW_BUTTON:
            tty_print_string ("[");
            break;
        case HIDDEN_BUTTON:
        default:
            return MSG_HANDLED;
        }

        hotkey_draw (w, b->text, focused);

        switch (b->flags)
        {
        case DEFPUSH_BUTTON:
            tty_print_string (" >]");
            break;
        case NORMAL_BUTTON:
            tty_print_string (" ]");
            break;
        case NARROW_BUTTON:
            tty_print_string ("]");
            break;
        default:
            break;
        }

        return MSG_HANDLED;
    }

    case MSG_DESTROY:
        hotkey_free (b->text);
        return MSG_HANDLED;

    default:
        return widget_default_callback (w, sender, msg, parm, data);
    }
}

void
button_mouse_default_callback (Widget *w, mouse_msg_t msg, mouse_event_t *event)
{
    (void) event;

    switch (msg)
    {
    case MSG_MOUSE_DOWN:
        widget_select (w);
        break;

    case MSG_MOUSE_CLICK:
        send_message (w, NULL, MSG_KEY, ' ', NULL);
        send_message (w->owner, w, MSG_POST_KEY, ' ', NULL);
        break;

    default:
        break;
    }
}

WButton *
button_new (int y, int x, int action, button_flags_t flags, const char *text, bcback_fn callback)
{
    WRect r = { y, x, 1, 1 };
    WButton *b;
    Widget *w;

    b = g_new (WButton, 1);
    w = WIDGET (b);

    b->action = action;
    b->flags = flags;
    b->text = hotkey_new (text);
    r.cols = button_get_width (b);
    widget_init (w, &r, button_default_callback, button_mouse_default_callback);
    w->options |= WOP_SELECTABLE | WOP_WANT_CURSOR | WOP_WANT_HOTKEY;
    b->callback = callback;
    b->hotpos = (b->text.hotkey != NULL) ? str_term_width1 (b->text.start) : -1;

    return b;
}

char *
button_get_text (const WButton *b)
{
    return hotkey_get_text (b->text);
}

void
button_set_text (WButton *b, const char *text)
{
    Widget *w = WIDGET (b);
    hotkey_t hk;

    hk = hotkey_new (text);
    if (hotkey_equal (b->text, hk))
    {
        hotkey_free (hk);
        return;
    }

    hotkey_free (b->text);
    b->text = hk;
    b->hotpos = (b->text.hotkey != NULL) ? str_term_width1 (b->text.start) : -1;
    w->rect.cols = button_get_width (b);
    widget_draw (w);
}

int
button_get_width (const WButton *b)
{
    int ret = hotkey_width (b->text);

    switch (b->flags)
    {
    case DEFPUSH_BUTTON:
        ret += 6;
        break;
    case NORMAL_BUTTON:
        ret += 4;
        break;
    case NARROW_BUTTON:
        ret += 2;
        break;
    case HIDDEN_BUTTON:
    default:
        return 0;
    }

    return ret;
}

void
add_hook (hook_t **hook_list, void (*hook_fn) (void *), void *data)
{
    hook_t *new_hook = g_new (hook_t, 1);

    new_hook->hook_fn = hook_fn;
    new_hook->next = *hook_list;
    new_hook->hook_data = data;

    *hook_list = new_hook;
}

void
execute_hooks (hook_t *hook_list)
{
    hook_t *new_hook = NULL;
    hook_t *p;

    /* We copy the hook list first so tahat we let the hook
     * function call delete_hook
     */

    while (hook_list != NULL)
    {
        add_hook (&new_hook, hook_list->hook_fn, hook_list->hook_data);
        hook_list = hook_list->next;
    }
    p = new_hook;

    while (new_hook != NULL)
    {
        new_hook->hook_fn (new_hook->hook_data);
        new_hook = new_hook->next;
    }

    for (hook_list = p; hook_list != NULL;)
    {
        p = hook_list;
        hook_list = hook_list->next;
        g_free (p);
    }
}

void
delete_hook (hook_t **hook_list, void (*hook_fn) (void *))
{
    hook_t *new_list = NULL;
    hook_t *current, *next;

    for (current = *hook_list; current != NULL; current = next)
    {
        next = current->next;
        if (current->hook_fn == hook_fn)
            g_free (current);
        else
            add_hook (&new_list, current->hook_fn, current->hook_data);
    }
    *hook_list = new_list;
}

gboolean
hook_present (hook_t *hook_list, void (*hook_fn) (void *))
{
    hook_t *p;

    for (p = hook_list; p != NULL; p = p->next)
        if (p->hook_fn == hook_fn)
            return TRUE;
    return FALSE;
}

char *strchr(const char *s, int c)
{
	while (*s != (char)c) {
		if (!*s)
			return NULL;
		s++;
	}

	return (char *)s;
}

char *strpbrk(const char *s1, const char *s2)
{
  const char *c = s2;
  if (!*s1)
    return (char *) NULL;

  while (*s1)
    {
      for (c = s2; *c; c++)
	{
	  if (*s1 == *c)
	    break;
	}
      if (*c)
	break;
      s1++;
    }

  if (*c == '\0')
    s1 = NULL;

  return (char *) s1;
}

static void KBD_Poll(void) {
	while (adb_kbd_poll());
	usb_poll();
}

UCHAR IOSKBD_ReadChar() {
	while (s_Buffer.ReadIndex == s_Buffer.WriteIndex) {
		KBD_Poll();
	}
	s_Buffer.ReadIndex = INCREMENT_INDEX_READ();
	return s_Buffer.Buffer[s_Buffer.ReadIndex];
}

bool IOSKBD_CharAvailable() {
	KBD_Poll();
	return s_Buffer.ReadIndex != s_Buffer.WriteIndex;
}

static void KBDWriteChar(UCHAR Character) {
	UCHAR IncWrite = INCREMENT_INDEX_WRITE();
	if (IncWrite != s_Buffer.ReadIndex) {
		s_Buffer.WriteIndex = IncWrite;
		s_Buffer.Buffer[s_Buffer.WriteIndex] = Character;
	}
}

static void KBDWriteKey(BYTE keycode, BYTE modifier) {
	if (keycode < KEY_VALID_START) return;

	if (keycode == KEY_CAPSLOCK) {
		s_CapsLock ^= 1;
		return;
	}
	if (keycode == KEY_SYSRQ) {
		KBDWriteChar('\x80');
		return;
	}
	if (keycode >= KEY_LOOKUP_START && keycode <= KEY_LOOKUP_END) {
		if (s_CapsLock && keycode >= KEY_LOOKUP_START && keycode <= (KEY_LOOKUP_START + 26)) {
			if (modifier & KEY_MODIFIER_SHIFT) modifier &= ~KEY_MODIFIER_SHIFT;
			else modifier |= KEY_MODIFIER_SHIFT;
		}
		if (modifier & KEY_MODIFIER_SHIFT) {
			KBDWriteChar(s_LookupShift[keycode - KEY_LOOKUP_START]);
		}
		else {
			KBDWriteChar(s_LookupNormal[keycode - KEY_LOOKUP_START]);
		}
		return;
	}

	UCHAR ControlChar = 0;

	if (keycode >= KEY_F1 && keycode <= KEY_F12) {
		// This table comes from the ARC specification (ARC/riscspec.pdf) page 105.
		static const char s_ControlChars[] = "PQwxtuqrpMAB";
		KBDWriteChar('\x9b');
		KBDWriteChar('O');
		KBDWriteChar(s_ControlChars[keycode - KEY_F1]);
		return;
	}

	switch (keycode) {
	case KEY_UP:
		ControlChar = 'A';
		break;

	case KEY_DOWN:
		ControlChar = 'B';
		break;

	case KEY_RIGHT:
		ControlChar = 'C';
		break;

	case KEY_LEFT:
		ControlChar = 'D';
		break;

	case KEY_HOME:
		ControlChar = 'H';
		break;

	case KEY_END:
		ControlChar = 'K';
		break;

	case KEY_PAGEUP:
		ControlChar = '?';
		break;

	case KEY_PAGEDOWN:
		ControlChar = '/';
		break;

	case KEY_INSERT:
		ControlChar = '@';
		break;

	case KEY_DELETE:
		ControlChar = 'P';
		break;
	}

	if (ControlChar == 0) return;
	KBDWriteChar('\x9b');
	KBDWriteChar(ControlChar);
}

void KBDOnEvent(PUSB_KBD_REPORT Report) {
	// Only support the first key pressed.
	// Do not check modifier, this prevents things like "press shift, press ;:, release shift first" to input ":;"
	//if (s_LastKeycode == s_Event.report.keycode[0] && s_LastModifier == s_Event.report.modifier) return;
	if (s_LastKeycode == Report->KeyCode[0]) return;
	s_LastKeycode = Report->KeyCode[0];
	s_LastModifier = Report->Modifiers;
	KBDWriteKey(s_LastKeycode, s_LastModifier);
}

static bool AkpKeyIsModifier(UCHAR AdbScanCode) {
	switch (AdbScanCode) {
	case ADB_KEY_LCTRL:
