static int strcut(char *str, int begin, int len) {
    size_t l;
    l = strlen(str);

    if ((int)l < 0 || (int)l > MAX_SAFE_INT)
        return -1;

    if (len < 0)
        len = l - begin + 1;
    if (begin + len > (int)l)
        len = l - begin;
    memmove(str + begin, str + begin + len, l - len + 1 - begin);

    return len;
}

static int has_valid_chars(const char *str, const char *matrix) {
    size_t len;
    size_t mlen;
    len = strlen(str);
    mlen = strlen(matrix);

    for (size_t i = 0; i < len; i++)
        if (contains(str[i], matrix, mlen) == 0)
            return 0;

    return 1;
}

static int binary_comparison(int x, int y) {
    if (x == y)
        return 0;
    if (x > y)
        return 1;
    return -1;
}

static int parse_int(const char *s) {
    int valid;
    int num;
    valid = has_valid_chars(s, NUMBERS);
    if (valid == 0)
        return -1;

    num = strtol(s, NULL, 10);
    if (num > MAX_SAFE_INT)
        return -1;

    return num;
}

static char *parse_slice(const char *buf, char sep) {
    char *pr;
    char *part;
    int plen;

    /* Find separator in buf */
    pr = strchr(buf, sep);
    if (pr == NULL)
        return NULL;
    /* Length from separator to end of buf */
    plen = strlen(pr);

    /* Copy from buf into new string */
    part = (char *)calloc(plen + 1, sizeof(*part));
    if (part == NULL)
        return NULL;
    memcpy(part, pr + 1, plen);
    /* Null terminate new string */
    part[plen] = '\0';

    /* Terminate buf where separator was */
    *pr = '\0';

    return part;
}

int semver_parse(const char *str, semver_t *ver) {
    int valid;
    int res;
    size_t len;
    char *buf;
    valid = semver_is_valid(str);
    if (!valid)
        return -1;

    len = strlen(str);
    buf = (char *)calloc(len + 1, sizeof(*buf));
    if (buf == NULL)
        return -1;
    strcpy(buf, str);

    ver->metadata = parse_slice(buf, MT_DELIMITER[0]);
    ver->prerelease = parse_slice(buf, PR_DELIMITER[0]);

    res = semver_parse_version(buf, ver);
    free(buf);
#if DEBUG > 0
    printf("[debug] semver.c %s = %d.%d.%d, %s %s\n", str, ver->major, ver->minor, ver->patch, ver->prerelease, ver->metadata);
#endif
    return res;
}

int semver_parse_version(const char *str, semver_t *ver) {
    size_t len;
    int index;
    int value;
    char *slice;
    char *next;
    char *endptr;
    slice = (char *)str;
    index = 0;

    while (slice != NULL && index++ < 4) {
        next = strchr(slice, DELIMITER[0]);
        if (next == NULL)
            len = strlen(slice);
        else
            len = next - slice;
        if (len > SLICE_SIZE)
            return -1;

        /* Cast to integer and store */
        value = strtol(slice, &endptr, 10);
        if (endptr != next && *endptr != '\0')
            return -1;

        switch (index) {
        case 1:
            ver->major = value;
            break;
        case 2:
            ver->minor = value;
            break;
        case 3:
            ver->patch = value;
            break;
        default:
            break;
        }

        /* Continue with the next slice */
        if (next == NULL)
            slice = NULL;
        else
            slice = next + 1;
    }

    return 0;
}

void append(char **str1, const char *str2){
    assert(str1);
    assert(str2);
    size_t len = (*str1 ? strlen(*str1) : 0) + strlen(str2);

    char *concatenated = (char *)malloc(len + 1);
    concatenated[0] = 0;
    assert(concatenated);

    if (*str1) {
        strcpy(concatenated, *str1);
        free(*str1);
    }
    strcat(concatenated, str2);

    *str1 = concatenated;
}

int RayPlaneIntersection(const Vector3 RayOrigin, const Vector3 RayDirection, const Vector3 PlanePoint, const Vector3 PlaneNormal, Vector3 *IntersectionPoint) {
    float dotProduct = (PlaneNormal.x * RayDirection.x) + (PlaneNormal.y * RayDirection.y) + (PlaneNormal.z * RayDirection.z);

    // Check if the ray is parallel to the plane
    if (dotProduct == 0.0f) {
        return 0;
    }

    float t = ((PlanePoint.x - RayOrigin.x) * PlaneNormal.x + (PlanePoint.y - RayOrigin.y) * PlaneNormal.y + (PlanePoint.z - RayOrigin.z) * PlaneNormal.z) / dotProduct;

    IntersectionPoint->x = RayOrigin.x + t * RayDirection.x;
    IntersectionPoint->y = RayOrigin.y + t * RayDirection.y;
    IntersectionPoint->z = RayOrigin.z + t * RayDirection.z;

    return 1;
}

Vector3 WorldToCamera(Vector3 worldPos, Matrix cameraMatrix) {
    return  Vector3Transform(worldPos, cameraMatrix);
}

Vector3 CameraToWorld(Vector3 worldPos, Matrix cameraMatrix) {
    return Vector3Transform(worldPos, MatrixInvert(cameraMatrix));
}

Vector3 VectorProjection(const Vector3 vectorToProject, const Vector3 targetVector) {
    float dotProduct = (vectorToProject.x * targetVector.x) +
                      (vectorToProject.y * targetVector.y) +
                      (vectorToProject.z * targetVector.z);

    float targetVectorLengthSquared = (targetVector.x * targetVector.x) +
                                      (targetVector.y * targetVector.y) +
                                      (targetVector.z * targetVector.z);

    float scale = dotProduct / targetVectorLengthSquared;

    Vector3 projection;
    projection.x = targetVector.x * scale;
    projection.y = targetVector.y * scale;
    projection.z = targetVector.z * scale;

    return projection;
}

Vector3 NearestPointOnLine(Vector3 p1,
                           Vector3 p2,
                           Vector3 p3,
                           Vector3 p4)
{
    float mua;

    Vector3 p13,p43,p21;
    float d1343,d4321,d1321,d4343,d2121;
    float numer,denom;

    const float EPS = 0.001;

    p13.x = p1.x - p3.x;
    p13.y = p1.y - p3.y;
    p13.z = p1.z - p3.z;
    p43.x = p4.x - p3.x;
    p43.y = p4.y - p3.y;
    p43.z = p4.z - p3.z;
    if (fabs(p43.x) < EPS && fabs(p43.y) < EPS && fabs(p43.z) < EPS)
        return(Vector3){};
    p21.x = p2.x - p1.x;
    p21.y = p2.y - p1.y;
    p21.z = p2.z - p1.z;
    if (fabs(p21.x) < EPS && fabs(p21.y) < EPS && fabs(p21.z) < EPS)
        return(Vector3){};

    d1343 = p13.x * p43.x + p13.y * p43.y + p13.z * p43.z;
    d4321 = p43.x * p21.x + p43.y * p21.y + p43.z * p21.z;
    d1321 = p13.x * p21.x + p13.y * p21.y + p13.z * p21.z;
    d4343 = p43.x * p43.x + p43.y * p43.y + p43.z * p43.z;
    d2121 = p21.x * p21.x + p21.y * p21.y + p21.z * p21.z;

    denom = d2121 * d4343 - d4321 * d4321;
    if (fabs(denom) < EPS)
        return (Vector3){};
    numer = d1343 * d4321 - d1321 * d4343;

    mua = numer / denom;

    return (Vector3){ 
        p1.x + mua * p21.x,
        p1.y + mua * p21.y,
        p1.z + mua * p21.z};

}

BoundingBox boundingBoxSized(Vector3 center, float size) {
    return (BoundingBox){
        Vector3SubtractValue(center, size/2),
        Vector3AddValue(center, size/2),
    };
}

BoundingBox shapeBoundingBox(Sphere s) {
    // const float radius = sqrtf(powf(s.size.x, 2) + powf(s.size.y, 2) + powf(s.size.z, 2));
    return (BoundingBox){
        Vector3Subtract(s.pos, s.size),
        Vector3Add(s.pos, s.size),
    };
}

int GuiFloatValueBox(Rectangle bounds, const char *text, float *value, float minValue, float maxValue, bool editMode)
{
    #if !defined(RAYGUI_VALUEBOX_MAX_CHARS)
        #define RAYGUI_VALUEBOX_MAX_CHARS  32
    #endif

    int result = 0;
    GuiState state = guiState;

    static char editingTextValue[RAYGUI_VALUEBOX_MAX_CHARS + 1] = "\0";
    char textValue[RAYGUI_VALUEBOX_MAX_CHARS + 1] = "\0";
    static float original_value;
    static int key_delay = 0;
    snprintf(textValue, RAYGUI_VALUEBOX_MAX_CHARS, "%g", *value);

    Rectangle textBounds = { 0 };
    if (text != NULL)
    {
        textBounds.width = (float)(GetTextWidth(text) + 2);
        textBounds.height = (float)(GuiGetStyle(DEFAULT, TEXT_SIZE));
        textBounds.x = bounds.x + bounds.width + GuiGetStyle(VALUEBOX, TEXT_PADDING);
        textBounds.y = bounds.y + bounds.height/2 - GuiGetStyle(DEFAULT, TEXT_SIZE)/2;
        if (GuiGetStyle(VALUEBOX, TEXT_ALIGNMENT) == TEXT_ALIGN_LEFT) textBounds.x = bounds.x - textBounds.width - GuiGetStyle(VALUEBOX, TEXT_PADDING);
    }

    char *text_to_display = textValue;

    // Update control
    //--------------------------------------------------------------------
    if ((state != STATE_DISABLED) && !guiLocked && !guiSliderDragging)
    {
        Vector2 mousePoint = GetMousePosition();

        bool valueHasChanged = false;

        if (editMode)
        {   
            state = STATE_PRESSED;

            int keyCount = (int)strlen(editingTextValue);

            // Only allow keys in range [48..57]
            if (keyCount < RAYGUI_VALUEBOX_MAX_CHARS)
            {
                int key = GetCharPressed();
                if (((key >= 48) && (key <= 57)) || key == 46)
                {
                    editingTextValue[keyCount] = (char)key;
                    keyCount++;
                    valueHasChanged = true;
                }
            }

            // Delete text
            if (keyCount > 0)
            {
                if (IsKeyPressed(KEY_BACKSPACE))
                {
                    keyCount--;
                    editingTextValue[keyCount] = '\0';
                    valueHasChanged = true;
                }
            }

            if (!valueHasChanged && IsKeyDown(KEY_UP) && key_delay <= 0) {
                *value+=fabs(*value*0.1) + 0.1;
                if (*value > maxValue) *value = maxValue;
                key_delay=9;
                sprintf(editingTextValue, "%g", *value);
            }else if (!valueHasChanged && IsKeyDown(KEY_DOWN) && key_delay <= 0) {
                *value-=fabs(*value*0.1) + 0.1;
                if (*value < minValue) *value = minValue;
                key_delay=9;
                sprintf(editingTextValue, "%g", *value);
            }

            if (key_delay > 0) key_delay--;
            if (!IsKeyDown(KEY_UP) && !IsKeyDown(KEY_DOWN))key_delay = 0;
            text_to_display = editingTextValue;
            if (IsKeyPressed(KEY_ESCAPE)) {
                *value = original_value;
                result = 1;
            } else {
                if (valueHasChanged) *value = (float)strtod(editingTextValue, NULL);
                if (IsKeyPressed(KEY_ENTER) || (!CheckCollisionPointRec(mousePoint, bounds) && IsMouseButtonPressed(MOUSE_LEFT_BUTTON))) result = 1;
            }
        }
        else
        {
            if (*value > maxValue) *value = maxValue;
            else if (*value < minValue) *value = minValue;

            if (CheckCollisionPointRec(mousePoint, bounds))
            {
                state = STATE_FOCUSED;
                if (IsMouseButtonPressed(MOUSE_LEFT_BUTTON)) {
                    original_value = *value;
                    memcpy(editingTextValue, textValue, RAYGUI_VALUEBOX_MAX_CHARS + 1);
                    result = 1;
                }
            }
        }
    }
    //--------------------------------------------------------------------

    // Draw control
    //--------------------------------------------------------------------
    Color baseColor = BLANK;
    if (state == STATE_PRESSED) baseColor = GetColor(GuiGetStyle(VALUEBOX, BASE_COLOR_PRESSED));
    else if (state == STATE_DISABLED)  baseColor = GetColor(GuiGetStyle(VALUEBOX, BASE_COLOR_DISABLED));
    else if (state == STATE_FOCUSED) baseColor = WHITE;

    GuiDrawRectangle(bounds, 0, GetColor(GuiGetStyle(VALUEBOX, BORDER + (state*3))), baseColor);
    GuiDrawText(text_to_display, GetTextBounds(VALUEBOX, bounds), TEXT_ALIGN_LEFT, GetColor(GuiGetStyle(VALUEBOX, TEXT)));

    // Draw cursor
    if (editMode)
    {
        Rectangle cursor = { bounds.x + GetTextWidth(text_to_display) + 1, bounds.y + 2*GuiGetStyle(VALUEBOX, BORDER_WIDTH), 4, bounds.height - 4*GuiGetStyle(VALUEBOX, BORDER_WIDTH) };
        GuiDrawRectangle(cursor, 0, BLANK, GetColor(GuiGetStyle(LABEL, TEXT + (state*3))));
    }

    // Draw text label if provided
    GuiDrawText(text, textBounds, (GuiGetStyle(VALUEBOX, TEXT_ALIGNMENT) == TEXT_ALIGN_RIGHT)? TEXT_ALIGN_LEFT : TEXT_ALIGN_RIGHT, GetColor(GuiGetStyle(LABEL, TEXT)));
    //--------------------------------------------------------------------

    return result;
}

void append_map_function(char **result, bool use_color_as_index, int dynamic_index) {

    char *map = NULL;

    append(&map, "uniform vec3 selectionValues[5];\n\n");

    #if DEMO_VIDEO_FEATURES
    if (false_color_mode) {
        append(&map, "#define FALSE_COLOR_MODE 1\n\n");
    }
    #endif

    append(&map,
        "vec4 signed_distance_field( in vec3 pos ){\n"
        "\tvec4 distance = vec4(999999.,0,0,0);\n");

    for (int i=0; i < num_spheres; i++) {
        Sphere s = spheres[i];
        float used_radius = fmaxf(0.01,fminf(s.corner_radius, fminf(s.size.x,fminf(s.size.y, s.size.z))));

        char *symmetry[8] = {
        "",
        "opSymX",
        "opSymY",
        "opSymXY", 
        "opSymZ",
        "opSymXZ",
        "opSymYZ",
        "opSymXYZ"};

        int mirror_index = (s.mirror.z << 2) | (s.mirror.y << 1) | s.mirror.x;
        if (i == dynamic_index) {
            append(&map, TextFormat("\tdistance = %s(\n"
                              "\t\tvec4(RoundBox(\n"
                              "\t\t\t\topRotateXYZ(\n"
                              "\t\t\t\t\t%s(pos) - selectionValues[0], // position\n"
                              "\t\t\t\t\tselectionValues[1]), // angle\n"
                              "\t\t\t\tselectionValues[2],  // size\n"
                              "\t\t\t\tselectionValues[4].x), // corner radius\n"
                              "\t\t\tselectionValues[3]), // color\n"
                              "\t\tdistance,\n\t\tselectionValues[4].y); // blobbyness\n",
                              s.subtract ? "opSmoothSubtraction" : "BlobbyMin",
                              symmetry[mirror_index]));
        } else {

            uint8_t r = use_color_as_index ?  (uint8_t)(i+1) : s.color.r;
            uint8_t g = use_color_as_index ?  0 : s.color.g;
            uint8_t b = use_color_as_index ?  0 : s.color.b;

#           if DEMO_VIDEO_FEATURES
            if (false_color_mode) {
                Color c = ColorFromHSV((i*97) % 360, 1, 0.5);
                r = c.r;
                g = c.g;
                b = c.b;
            }
#           endif


            char *opName = s.subtract ? "opSmoothSubtraction" : ((use_color_as_index
                                                                #if DEMO_VIDEO_FEATURES
                                                                  || false_color_mode
                                                                #endif
                                                                  ) ? "opSmoothUnionSteppedColor" : (s.blob_amount > 0 ? "BlobbyMin" : "Min"));
            append(&map,  TextFormat("\tdistance = %s(\n\t\tvec4(RoundBox(\n", opName));

            const bool rotated = fabsf(s.angle.x) > .01 || fabsf(s.angle.y) > 0.01 || fabsf(s.angle.z) > .01;
            if (rotated) {
                    float cz = cos(s.angle.z);
                    float sz = sin(s.angle.z);
                    float cy = cos(s.angle.y);
                    float sy = sin(s.angle.y);
                    float cx = cos(s.angle.x);
                    float sx = sin(s.angle.x);

                    append(&map, TextFormat("\t\t\tmat3(%g, %g, %g,"
                                            "%g, %g, %g,"
                                            "%g, %g, %g)*\n",
                                            cz*cy,
                                            cz*sy*sx - cx*sz,
                                            sz*sx + cz*cx*sy,

                                            cy*sz,
                                            cz*cx + sz*sy*sx,
                                            cx*sz*sy - cz*sx,

                                            -sy,
                                            cy*sx,
                                            cy*cx
                                            ));
            }

            append(&map, TextFormat("\t\t\t\t(%s(pos) - vec3(%g,%g,%g)), // position\n",
                                  symmetry[mirror_index],
                                  s.pos.x, s.pos.y, s.pos.z));



            append(&map, TextFormat("\t\t\tvec3(%g,%g,%g),// size\n"
                              "\t\t\t%g), // corner radius\n"
                              "\t\t\t%g,%g,%g), // color\n"
                              "\t\tdistance",
                              s.size.x-used_radius, s.size.y-used_radius, s.size.z-used_radius,
                              used_radius,
                              r/255.f, g/255.f, b/255.f));

            if (!strcmp(opName, "Min")) {
                append(&map,  TextFormat(");\n"));
            } else {
                append(&map,  TextFormat(",\n\t\t%g);  // blobbyness\n", fmaxf(s.blob_amount, 0.0001)));
            }

        }


    }

    append(&map, "\treturn distance;\n}\n");

#   if DEMO_VIDEO_FEATURES
    SaveFileText("map.glsl", map);
#   endif

    append(result, map);
    free(map);
}

TTP_NOTRACE void ttpoe_pretty_print_data (const u8 *caption, const int bpl,
                                          const u8 *buf, const int buflen)
{
    int len = buflen;

    if (ttp_verbose < 2) {
        return;
    }

    do {
        scnprintf (ttpoe_prbuf, TTPOE_PRBUF_MAX, "%*ph", min (len, bpl), buf);
        TTP_DBG ("%s%s\n", caption, ttpoe_prbuf);

        buf += bpl;
        if (len > bpl) {
            len -= bpl;
        }
        else {
            len = 0;
        }
    } while (len);
}

TTP_NOTRACE void ttp_print_tag_val (struct seq_file *seq, const struct ttp_link_tag *lt)
{
    struct ttp_fsm_event *ev;

    if (!seq || !lt || !lt->valid) {
        return;
    }

    seq_printf (seq, "%3d %1d %1d %2d  %2s  %d %d %d    %02x:%02x:%02x %2d"
                "   %6d   %6d   %6d   %6d   0x%016llx\n",
                lt->hvl,
                lt->valid,
                lt->bkt,
                lt->vci,
                TTP_STATE_NAME_SH (lt->state),
                lt->tct,
                lt->txt,
                lt->try,
                lt->mac[0], lt->mac[1], lt->mac[2],
                lt->gwf | (lt->tip << 1),
                lt->rx_seq_id,
                lt->tx_seq_id,
                lt->retire_id,
                atomic_read (&lt->opens),
                cpu_to_be64 (lt->_rkid));

    if (lt->tct) {
        if (!mutex_trylock (&ttp_global_root_head.event_mutx)) {
            return;
        }
        list_for_each_entry (ev, &lt->ncq, elm) {
            ttp_print_evt_val (seq, ev);
        }

        mutex_unlock (&ttp_global_root_head.event_mutx);
    }
}

TTP_NOTRACE
void ttpoe_parse_print (const struct sk_buff *skb, enum ttp_frame_direction dir, int lv)
{
    u16 etype;
    char *sdir;
    struct ttp_frame_hdr frh;
    struct ttp_pkt_info  pif = {0};

    if (ttp_verbose <= lv) {
        return;
    }

    etype = ttp_skb_pars (skb, &frh, &pif);
    switch (dir) {
    case TTP_RX:
        sdir = ">>>> RXQ";
        break;
    case TTP_TX:
        sdir = "<<<< TXQ";
        break;
    }

    TTP_VBG ("+---- Parse %s frame: (skb-len: %d) (noc-len: %d) ---+\n",
             sdir, skb->len, pif.noc_len);
    TTP_RAW ((u8 *)skb->data, skb->len);

    if (ttp_verbose > lv) {
        ttp_print_eth_hdr (frh.eth);
    }
    switch (etype) {
    case TESLA_ETH_P_TTPOE:
        ttp_print_tsla_type_hdr (frh.tth);
        ttp_print_shim_hdr (frh.tsh);
        break;
    case ETH_P_IP:
        ttp_print_ipv4_hdr (frh.ip4);
        ttp_print_udp_hdr (frh.udp);
        break;
    case ETH_P_IPV6:
        ttp_print_ipv6_hdr (frh.ip6);
        ttp_print_udp_hdr (frh.udp);
        break;
    default:
        return;
    }

    TTP_VBG ("Conn:   vers: %1d res-op: %1d     opcode: %1d [ %s ]\n",
             frh.ttp->conn_version, frh.ttp->res_opcode, frh.ttp->conn_opcode,
             TTP_OPCODE_NAME (frh.ttp->conn_opcode));

    if (frh.ttp->conn_version) {
        TTP_VBG ("Conn:  vc-id: %1d   res0: %*phC  epoch: %-2d\n",
                 frh.ttp->conn_vc,
                 (int)sizeof (frh.ttp->conn_reserved0), &frh.ttp->conn_reserved0,
                 ntohs (frh.ttp->conn_epoch));

        TTP_VBG ("Conn:  congn: %-2d r1/r2: %1x/%1x    cr/ce: %d/%d  extn: %-2d\n",
                 frh.ttp->conn_congestion, frh.ttp->conn_res1, frh.ttp->conn_res2,
                 frh.ttp->conn_congn_reduced, frh.ttp->conn_congn_reduced_echo,
                 frh.ttp->conn_extension);
    }
    else {                      /* backward-compat: version-0 = layer-2 */
        TTP_VBG ("Conn:  vc-id: %1d  tx/rx: %d/%d    epoch: %-2d\n",
                 frh.ttp->conn_vc, frh.ttp->conn_tx, frh.ttp->conn_rx,
                 ntohs (frh.ttp->conn_epoch));

        TTP_VBG ("Conn:  congn: %-2d  res1: %*phC   extn: %-2d\n",
                 frh.ttp->conn_congestion,
                 (int)sizeof (frh.ttp->conn_reserved1), &frh.ttp->conn_reserved1,
                 frh.ttp->conn_extension);
    }

    TTP_VBG ("Conn: tx_seq: %-7u         rx_seq: %-7u\n",
             ntohl (frh.ttp->conn_tx_seq), ntohl (frh.ttp->conn_rx_seq));

    if (pif.noc_len) {
        TTP_VBG (" NOC: tot-len: %zu\n", min ((size_t)pif.noc_len, sizeof (*frh.noc)));
        TTP_RAW ((u8 *)frh.noc, min ((size_t)pif.noc_len, sizeof (*frh.noc)));
    }
    if (pif.noc_len > sizeof (*frh.noc)) {
        TTP_VBG (" NOC: data-len: %d\n", pif.noc_len);
        TTP_RWS ((u8 *)frh.dat, pif.noc_len - sizeof (*frh.noc));
    }
}

static inline bool ttpip_is_ttp_dev (const u8 *name)
{
    return !strncmp (name, ttp_dev, IFNAMSIZ);
}

static void ttpip_mcast_mac_create (u8 *mac)
{
    u32 imac; /* holds lower 3 bytes - similar to shim */

    imac = htonl (0xFFFFFF << 8); /* makes each lower 3 byte = 0xff */
    ttp_prepare_mac_with_oui (mac, TESLA_MAC_OUI, (u8 *)&imac);
    mac[0] |= 0x3; /* convert to multicast link-local mac address */
}

static struct sk_buff *ttpip_skb_aloc (void)
{
    struct sk_buff *skb;
    u16 frame_len;

    frame_len = ETH_HLEN + 12;

    if (!(skb = alloc_skb (frame_len + TTP_IP_HEADROOM, GFP_ATOMIC))) {
        return NULL;
    }

    skb_reserve (skb, TTP_IP_HEADROOM);
    skb_reset_mac_header (skb);
    skb_set_network_header (skb, ETH_HLEN);

    skb->len = max (frame_len, TTP_MIN_FRAME_LEN);
    skb_trim (skb, skb->len);
    skb_set_tail_pointer (skb, skb->len);

    return skb;
}

static void ttpip_pretty_print_data (const u8 *caption, bool tx,
                                     const u8 *devname, const u8 *buf,
                                     int buflen, int trmlen)
{
    int len = !trmlen ? buflen : trmlen;

    TTP_DB2 ("%s %s dev: %s len: %d%s\n",
             caption, tx ? "<<- Tx" : "->> Rx", devname, buflen,
             (trmlen && (trmlen != buflen)) ? " (trimmed)" : "");
    do {
        TTP_DB2 ("%s %*ph\n", caption, min (len, 16), buf);
        buf += 16;
        len -= 16;
    } while (len > 0);
}

static inline bool ttp_zone_valid (int zn)
{
    bool rv;

    rv = !!((ttp_num_gwips) &&
            (zn > 0 && zn < TTP_MAX_NUM_ZONES) &&
            (ttp_zones[zn].ver == 4 || ttp_zones[zn].ver == 6));

    return rv;
}

static inline bool ttp_myzone (int zn)
{
    bool rv;

    rv = !!(ttp_num_gwips && (ttp_myzn == zn));
    return rv;
}

static void
_crypt_to64(char *s, unsigned long v, int n)
{
	while (--n >= 0)
	{
		*s++ = _crypt_a64[v & 0x3f];
		v >>= 6;
	}
}

char *
px_crypt_md5(const char *pw, const char *salt, char *passwd, unsigned dstlen)
{
	static char *magic = "$1$"; /* This string is magic for this algorithm.
								 * Having it this way, we can get better later
								 * on */
	static char *p;
	static const char *sp,
			   *ep;
	unsigned char final[MD5_SIZE];
	int			sl,
				pl,
				i;
	PX_MD	   *ctx,
			   *ctx1;
	int			err;
	unsigned long l;

	if (!passwd || dstlen < 120)
		return NULL;

	/* Refine the Salt first */
	sp = salt;

	/* If it starts with the magic string, then skip that */
	if (strncmp(sp, magic, strlen(magic)) == 0)
		sp += strlen(magic);

	/* It stops at the first '$', max 8 chars */
	for (ep = sp; *ep && *ep != '$' && ep < (sp + 8); ep++)
		continue;

	/* get the length of the true salt */
	sl = ep - sp;

	/* we need two PX_MD objects */
	err = px_find_digest("md5", &ctx);
	if (err)
		return NULL;
	err = px_find_digest("md5", &ctx1);
	if (err)
	{
		/* this path is possible under low-memory circumstances */
		px_md_free(ctx);
		return NULL;
	}

	/* The password first, since that is what is most unknown */
	px_md_update(ctx, (const uint8 *) pw, strlen(pw));

	/* Then our magic string */
	px_md_update(ctx, (uint8 *) magic, strlen(magic));

	/* Then the raw salt */
	px_md_update(ctx, (const uint8 *) sp, sl);

	/* Then just as many characters of the MD5(pw,salt,pw) */
	px_md_update(ctx1, (const uint8 *) pw, strlen(pw));
	px_md_update(ctx1, (const uint8 *) sp, sl);
	px_md_update(ctx1, (const uint8 *) pw, strlen(pw));
	px_md_finish(ctx1, final);
	for (pl = strlen(pw); pl > 0; pl -= MD5_SIZE)
		px_md_update(ctx, final, pl > MD5_SIZE ? MD5_SIZE : pl);

	/* Don't leave anything around in vm they could use. */
	px_memset(final, 0, sizeof final);

	/* Then something really weird... */
	for (i = strlen(pw); i; i >>= 1)
		if (i & 1)
			px_md_update(ctx, final, 1);
		else
			px_md_update(ctx, (const uint8 *) pw, 1);

	/* Now make the output string */
	strcpy(passwd, magic);
	strncat(passwd, sp, sl);
	strcat(passwd, "$");

	px_md_finish(ctx, final);

	/*
	 * and now, just to make sure things don't run too fast On a 60 Mhz
	 * Pentium this takes 34 msec, so you would need 30 seconds to build a
	 * 1000 entry dictionary...
	 */
	for (i = 0; i < 1000; i++)
	{
		px_md_reset(ctx1);
		if (i & 1)
			px_md_update(ctx1, (const uint8 *) pw, strlen(pw));
		else
			px_md_update(ctx1, final, MD5_SIZE);

		if (i % 3)
			px_md_update(ctx1, (const uint8 *) sp, sl);

		if (i % 7)
			px_md_update(ctx1, (const uint8 *) pw, strlen(pw));

		if (i & 1)
			px_md_update(ctx1, final, MD5_SIZE);
		else
			px_md_update(ctx1, (const uint8 *) pw, strlen(pw));
		px_md_finish(ctx1, final);
	}

	p = passwd + strlen(passwd);

	l = (final[0] << 16) | (final[6] << 8) | final[12];
	_crypt_to64(p, l, 4);
	p += 4;
	l = (final[1] << 16) | (final[7] << 8) | final[13];
	_crypt_to64(p, l, 4);
	p += 4;
	l = (final[2] << 16) | (final[8] << 8) | final[14];
	_crypt_to64(p, l, 4);
	p += 4;
	l = (final[3] << 16) | (final[9] << 8) | final[15];
	_crypt_to64(p, l, 4);
	p += 4;
	l = (final[4] << 16) | (final[10] << 8) | final[5];
	_crypt_to64(p, l, 4);
	p += 4;
	l = final[11];
	_crypt_to64(p, l, 2);
	p += 2;
	*p = '\0';

	/* Don't leave anything around in vm they could use. */
	px_memset(final, 0, sizeof final);

	px_md_free(ctx1);
	px_md_free(ctx);

	return passwd;
}

