SECTION( E ) VOID LdrHookImport( PVOID image, PVOID directory, ULONG hash, PVOID function ) 
{
    ULONG                       Djb = 0;
    PIMAGE_THUNK_DATA           Otd = NULL;
    PIMAGE_THUNK_DATA           Ntd = NULL;
    PIMAGE_IMPORT_BY_NAME       Ibn = NULL;
    PIMAGE_IMPORT_DESCRIPTOR    Imp = NULL;

    for( Imp = C_PTR( directory ) ; Imp->Name != 0 ; ++Imp )
    {
        Otd = C_PTR( U_PTR( image ) + Imp->OriginalFirstThunk );
        Ntd = C_PTR( U_PTR( image ) + Imp->FirstThunk );

        for( ; Otd->u1.AddressOfData != 0 ; ++Otd, ++Ntd )
        {
            if( ! IMAGE_SNAP_BY_ORDINAL( Otd->u1.Ordinal ) )
            {
                Ibn = C_PTR( U_PTR( image ) + Otd->u1.AddressOfData );
                Djb = HashString( Ibn->Name, 0 );

                if( Djb == hash )
                {
                    Ntd->u1.Function = ( ULONGLONG )C_PTR( function );
                };
            };
        };
    };
}

SECTION( E ) PVOID FindFunction( PVOID image, ULONG hash ) 
{
    ULONG                       Idx = 0;
    PUINT16                     Aoo = NULL;
    PUINT32                     Aof = NULL;
    PUINT32                     Aon = NULL;
    PIMAGE_DOS_HEADER           Hdr = NULL;
    PIMAGE_NT_HEADERS           Nth = NULL;
    PIMAGE_DATA_DIRECTORY       Dir = NULL;
    PIMAGE_EXPORT_DIRECTORY     Exp = NULL;

    Hdr = C_PTR( image );
    Nth = C_PTR( U_PTR( Hdr ) + Hdr->e_lfanew );
    Dir = & Nth->OptionalHeader.DataDirectory[ IMAGE_DIRECTORY_ENTRY_EXPORT ];

    if( Dir->VirtualAddress )
    {
        Exp = C_PTR( U_PTR( Hdr ) + Dir->VirtualAddress );
        Aon = C_PTR( U_PTR( Hdr ) + Exp->AddressOfNames );
        Aof = C_PTR( U_PTR( Hdr ) + Exp->AddressOfFunctions );
        Aoo = C_PTR( U_PTR( Hdr ) + Exp->AddressOfNameOrdinals );

        for( Idx = 0 ; Idx < Exp->NumberOfNames ; ++Idx )
        {
            if( HashString( C_PTR( U_PTR( Hdr ) + Aon[ Idx ] ), 0 ) == hash )
            {
                return C_PTR( U_PTR( Hdr ) + Aof[ Aoo[ Idx ] ] );
            };
        };
    };
    return NULL;
}

SECTION( E ) INT compare( PVOID stringA, PVOID stringB, SIZE_T length )
{
    PUCHAR A = stringA;
    PUCHAR B = stringB;

    do {
        if( *A++ != *B++ )
        {
            return( *--A - *--B );
        };
    } while( --length != 0 );

    return 0;
}

SECTION( E ) PVOID FindGadget( LPBYTE module, ULONG size )
{
	for( int x = 0; x < size; x++ )
	{
		if( compare( module + x, "\xFF\x23", 2 ) == 0 )
		{
            return ( LPVOID )( module + x );
		};
	};

    return NULL;
}

NTSTATUS
XGMDriverCreateDevice(
    _Inout_ PWDFDEVICE_INIT DeviceInit
    )
/*++

Routine Description:

    Worker routine called to create a device and its software resources.

Arguments:

    DeviceInit - Pointer to an opaque init structure. Memory for this
                    structure will be freed by the framework when the WdfDeviceCreate
                    succeeds. So don't access the structure after that point.

Return Value:

    NTSTATUS

--*/
{
    NTSTATUS                status;
    WDF_OBJECT_ATTRIBUTES   deviceAttributes;
    WDFDEVICE               device;
    PDEVICE_CONTEXT         deviceContext;
    PHID_DEVICE_ATTRIBUTES  hidAttributes;

    TraceEvents(TRACE_LEVEL_INFORMATION, TRACE_DRIVER, "Enter %!FUNC!");

    //
    // Mark ourselves as a filter, which also relinquishes power policy ownership
    //
    WdfFdoInitSetFilter(DeviceInit);

    WDF_OBJECT_ATTRIBUTES_INIT_CONTEXT_TYPE(
        &deviceAttributes,
        DEVICE_CONTEXT);

    status = WdfDeviceCreate(&DeviceInit,
        &deviceAttributes,
        &device);
    if (!NT_SUCCESS(status)) {
        TraceEvents(TRACE_LEVEL_ERROR, TRACE_DRIVER, "Error: WdfDeviceCreate failed %!STATUS!", status);
        return status;
    }

    deviceContext = GetDeviceContext(device);
    deviceContext->Device = device;
    deviceContext->DeviceData = 0;

    hidAttributes = &deviceContext->HidDeviceAttributes;
    RtlZeroMemory(hidAttributes, sizeof(HID_DEVICE_ATTRIBUTES));
    hidAttributes->Size = sizeof(HID_DEVICE_ATTRIBUTES);
    hidAttributes->VendorID = XGMDEVICE_VID;
    hidAttributes->ProductID = XGMDEVICE_PID;
    hidAttributes->VersionNumber = XGMDEVICE_VERSION;

    status = QueueCreate(device,
        &deviceContext->DefaultQueue);
    if (!NT_SUCCESS(status)) {
        return status;
    }

    status = ManualQueueCreate(device,
        &deviceContext->ManualQueue);
    if (!NT_SUCCESS(status)) {
        return status;
    }

    //
    // Use default "HID Descriptor" (hardcoded).
    //
    deviceContext->HidDescriptor = G_DefaultHidDescriptor;
    deviceContext->ReportDescriptor = G_DefaultReportDescriptor;

    return status;
}

NTSTATUS
RequestCopyFromBuffer(
    _In_  WDFREQUEST        Request,
    _In_  PVOID             SourceBuffer,
    _When_(NumBytesToCopyFrom == 0, __drv_reportError(NumBytesToCopyFrom cannot be zero))
    _In_  size_t            NumBytesToCopyFrom
)
/*++

Routine Description:

    A helper function to copy specified bytes to the request's output memory

Arguments:

    Request - A handle to a framework request object.

    SourceBuffer - The buffer to copy data from.

    NumBytesToCopyFrom - The length, in bytes, of data to be copied.

Return Value:

    NTSTATUS

--*/
{
    NTSTATUS                status;
    WDFMEMORY               memory;
    size_t                  outputBufferLength;

    status = WdfRequestRetrieveOutputMemory(Request, &memory);
    if (!NT_SUCCESS(status)) {
        TraceEvents(TRACE_LEVEL_ERROR, TRACE_DRIVER, "WdfRequestRetrieveOutputMemory failed %!STATUS!", status);
        return status;
    }

    WdfMemoryGetBuffer(memory, &outputBufferLength);
    if (outputBufferLength < NumBytesToCopyFrom) {
        status = STATUS_INVALID_BUFFER_SIZE;
        TraceEvents(TRACE_LEVEL_ERROR, TRACE_DRIVER, "RequestCopyFromBuffer: buffer too small. Size %d, expect %d",
            (int)outputBufferLength, (int)NumBytesToCopyFrom);
        return status;
    }

    status = WdfMemoryCopyFromBuffer(memory,
        0,
        SourceBuffer,
        NumBytesToCopyFrom);
    if (!NT_SUCCESS(status)) {
        TraceEvents(TRACE_LEVEL_ERROR, TRACE_DRIVER, "WdfMemoryCopyFromBuffer failed %!STATUS!", status);
        return status;
    }

    WdfRequestSetInformation(Request, NumBytesToCopyFrom);
    return status;
}

NTSTATUS
ReadReport(
    _In_  PQUEUE_CONTEXT    QueueContext,
    _In_  WDFREQUEST        Request,
    _Always_(_Out_)
    BOOLEAN* CompleteRequest
)
/*++

Routine Description:

    Handles IOCTL_HID_READ_REPORT for the HID collection. Normally the request
    will be forwarded to a manual queue for further process. In that case, the
    caller should not try to complete the request at this time, as the request
    will later be retrieved back from the manually queue and completed there.
    However, if for some reason the forwarding fails, the caller still need
    to complete the request with proper error code immediately.

Arguments:

    QueueContext - The object context associated with the queue

    Request - Pointer to  Request Packet.

    CompleteRequest - A boolean output value, indicating whether the caller
            should complete the request or not

Return Value:

    NT status code.

--*/
{
    NTSTATUS                status;

    TraceEvents(TRACE_LEVEL_INFORMATION, TRACE_DRIVER, "Enter %!FUNC!");

    //
    // forward the request to manual queue
    //
    status = WdfRequestForwardToIoQueue(
        Request,
        QueueContext->DeviceContext->ManualQueue);
    if (!NT_SUCCESS(status)) {
        TraceEvents(TRACE_LEVEL_ERROR, TRACE_DRIVER, "WdfRequestForwardToIoQueue failed %!STATUS!", status);
        *CompleteRequest = TRUE;
    }
    else {
        *CompleteRequest = FALSE;
    }

    return status;
}

