static void radio_device_loader_power_on() {
    uint8_t attempts = 0;
    while(!furi_hal_power_is_otg_enabled() && attempts++ < 5) {
        furi_hal_power_enable_otg();
        //CC1101 power-up time
        furi_delay_ms(10);
    }
}

static void radio_device_loader_power_off() {
    if(furi_hal_power_is_otg_enabled()) furi_hal_power_disable_otg();
}

bool radio_device_loader_is_connect_external(const char* name) {
    bool is_connect = false;
    bool is_otg_enabled = furi_hal_power_is_otg_enabled();

    if(!is_otg_enabled) {
        radio_device_loader_power_on();
    }

    const SubGhzDevice* device = subghz_devices_get_by_name(name);
    if(device) {
        is_connect = subghz_devices_is_connect(device);
    }

    if(!is_otg_enabled) {
        radio_device_loader_power_off();
    }
    return is_connect;
}

const SubGhzDevice* radio_device_loader_set(
    const SubGhzDevice* current_radio_device,
    SubGhzRadioDeviceType radio_device_type) {

    const SubGhzDevice* radio_device = NULL;

    if(radio_device_type == SubGhzRadioDeviceTypeExternalCC1101 &&
       radio_device_loader_is_connect_external(SUBGHZ_DEVICE_CC1101_EXT_NAME)) {
        radio_device_loader_power_on();
        radio_device = subghz_devices_get_by_name(SUBGHZ_DEVICE_CC1101_EXT_NAME);
        if (radio_device) {
            subghz_devices_begin(radio_device);
            FURI_LOG_D("radio_device_loader", "External CC1101 initialized.");
        } else {
            FURI_LOG_E("radio_device_loader", "Failed to initialize external CC1101.");
        }
    } else if (current_radio_device == NULL) {
        radio_device = subghz_devices_get_by_name(SUBGHZ_DEVICE_CC1101_INT_NAME);
        if (radio_device) {
            FURI_LOG_D("radio_device_loader", "Internal CC1101 selected.");
        } else {
            FURI_LOG_E("radio_device_loader", "Failed to load internal CC1101.");
        }
    } else {
        radio_device_loader_end(current_radio_device);
        radio_device = subghz_devices_get_by_name(SUBGHZ_DEVICE_CC1101_INT_NAME);
    }

    return radio_device;
}

bool radio_device_loader_is_external(const SubGhzDevice* radio_device) {
    furi_assert(radio_device);
    return (radio_device != subghz_devices_get_by_name(SUBGHZ_DEVICE_CC1101_INT_NAME));
}

void radio_device_loader_end(const SubGhzDevice* radio_device) {
    furi_assert(radio_device);
    radio_device_loader_power_off();
    if(radio_device != subghz_devices_get_by_name(SUBGHZ_DEVICE_CC1101_INT_NAME)) {
        subghz_devices_end(radio_device);
    }
}

int32_t jammer_app(void* p) {
    UNUSED(p);

    FURI_LOG_I(TAG, "Starting JammerApp");

    JammerApp* app = jammer_app_alloc();
    if(!app) {
        FURI_LOG_E(TAG, "Failed to allocate JammerApp");
        return -1;
    }

    jammer_show_splash_screen(app);

    if(!jammer_init_subghz(app)) {
        jammer_app_free(app);
        return -1;
    }

    jammer_start_tx(app);

    FURI_LOG_I(TAG, "Entering main loop");

    InputEvent event;
    while(app->running) {
        if(furi_message_queue_get(app->event_queue, &event, 10) == FuriStatusOk) {
            if(event.type == InputTypeShort) {
                switch(event.key) {
                    case InputKeyOk:
                        FURI_LOG_I(TAG, "OK button pressed");
                        jammer_switch_mode(app);
                        jammer_update_view(app);
                        break;
                    case InputKeyBack:
                        FURI_LOG_I(TAG, "Back button pressed");
                        app->running = false;
                        break;
                    case InputKeyRight:
                        FURI_LOG_I(TAG, "Right button pressed");
                        if(app->cursor_position < 4) {
                            app->cursor_position++;
                            jammer_update_view(app);
                        }
                        break;
                    case InputKeyLeft:
                        FURI_LOG_I(TAG, "Left button pressed");
                        if(app->cursor_position > 0) {
                            app->cursor_position--;
                            jammer_update_view(app);
                        }
                        break;
                    case InputKeyUp:
                        FURI_LOG_I(TAG, "Up button pressed");
                        jammer_adjust_frequency(app, true);
                        jammer_update_view(app);
                        break;
                    case InputKeyDown:
                        FURI_LOG_I(TAG, "Down button pressed");
                        jammer_adjust_frequency(app, false);
                        jammer_update_view(app);
                        break;
                    default:
                        break;
                }
            }
        }
    }

    FURI_LOG_I(TAG, "Exiting JammerApp main loop");

    jammer_app_free(app);

    FURI_LOG_I(TAG, "JammerApp exited");

    return 0;
}

JammerApp* jammer_app_alloc(void) {
    JammerApp* app = malloc(sizeof(JammerApp));
    if(!app) {
        return NULL;
    }

    app->view_port = view_port_alloc();
    app->event_queue = furi_message_queue_alloc(8, sizeof(InputEvent));
    app->frequency = 315000000;
    app->cursor_position = 0;
    app->running = true;
    app->tx_running = false;
    app->jamming_mode = JammerModeOok650Async;
    app->gui = furi_record_open(RECORD_GUI);

    furi_hal_region_set(&unlockedRegion);

    view_port_draw_callback_set(app->view_port, jammer_draw_callback, app);
    view_port_input_callback_set(app->view_port, jammer_input_callback, app);
    gui_add_view_port(app->gui, app->view_port, GuiLayerFullscreen);

    app->tx_thread = NULL;
    app->subghz_txrx = NULL;
    app->device = NULL;

    subghz_devices_init();
    app->subghz_txrx = subghz_tx_rx_worker_alloc();

    furi_hal_power_suppress_charge_enter();

    return app;
}

void jammer_app_free(JammerApp* app) {
    furi_assert(app);

#ifdef FURI_DEBUG
    FURI_LOG_D(TAG, "Enter jammer_app_free");
#endif

    if(app->tx_running) {
        app->tx_running = false;
#ifdef FURI_DEBUG
        FURI_LOG_D(TAG, "Set tx_running to false");
#endif
    }

    if(app->tx_thread) {
#ifdef FURI_DEBUG
        FURI_LOG_D(TAG, "Joining tx_thread");
#endif
        furi_thread_join(app->tx_thread);
        furi_thread_free(app->tx_thread);
        app->tx_thread = NULL;
#ifdef FURI_DEBUG
        FURI_LOG_D(TAG, "tx_thread joined and freed");
#endif
    }

    if(app->subghz_txrx) {
        if(subghz_tx_rx_worker_is_running(app->subghz_txrx)) {
#ifdef FURI_DEBUG
            FURI_LOG_D(TAG, "subghz_txrx worker is running, stopping");
#endif
            subghz_tx_rx_worker_stop(app->subghz_txrx);
#ifdef FURI_DEBUG
            FURI_LOG_D(TAG, "subghz_txrx worker stopped");
#endif
        }
#ifdef FURI_DEBUG
        FURI_LOG_D(TAG, "Freeing subghz_txrx worker");
#endif
        subghz_tx_rx_worker_free(app->subghz_txrx);
        app->subghz_txrx = NULL;
#ifdef FURI_DEBUG
        FURI_LOG_D(TAG, "subghz_txrx worker freed");
#endif
    }

#ifdef FURI_DEBUG
    FURI_LOG_D(TAG, "Ending radio device");
#endif
    if(app->device) {
#ifdef FURI_DEBUG
        const char* device_name = app->device->name ? app->device->name : "Unknown";
        FURI_LOG_D(TAG, "Device name: %s", device_name);
#endif

        if(radio_device_loader_is_external(app->device)) {
#ifdef FURI_DEBUG
            FURI_LOG_D(TAG, "Device is external, performing manual cleanup");
#endif
            if(furi_hal_power_is_otg_enabled()) {
#ifdef FURI_DEBUG
                FURI_LOG_D(TAG, "OTG power is enabled, disabling");
#endif
                furi_hal_power_disable_otg();
#ifdef FURI_DEBUG
                FURI_LOG_D(TAG, "OTG power disabled");
#endif
            }
        } else {
#ifdef FURI_DEBUG
            FURI_LOG_D(TAG, "Device is internal, calling radio_device_loader_end");
#endif
            radio_device_loader_end(app->device);
#ifdef FURI_DEBUG
            FURI_LOG_D(TAG, "radio_device_loader_end completed");
#endif
        }

        app->device = NULL;
#ifdef FURI_DEBUG
        FURI_LOG_D(TAG, "Radio device ended");
#endif
    }

#ifdef FURI_DEBUG
    FURI_LOG_D(TAG, "Calling subghz_devices_deinit");
#endif
    subghz_devices_deinit();
#ifdef FURI_DEBUG
    FURI_LOG_D(TAG, "subghz_devices_deinit completed");
#endif

#ifdef FURI_DEBUG
    FURI_LOG_D(TAG, "Exiting power suppression mode");
#endif
    furi_hal_power_suppress_charge_exit();

#ifdef FURI_DEBUG
    FURI_LOG_D(TAG, "Removing view port from GUI");
#endif
    gui_remove_view_port(app->gui, app->view_port);
#ifdef FURI_DEBUG
    FURI_LOG_D(TAG, "gui_remove_view_port completed");
#endif

    view_port_free(app->view_port);
#ifdef FURI_DEBUG
    FURI_LOG_D(TAG, "view_port freed");
#endif

#ifdef FURI_DEBUG
    FURI_LOG_D(TAG, "Closing GUI record");
#endif
    furi_record_close(RECORD_GUI);
#ifdef FURI_DEBUG
    FURI_LOG_D(TAG, "GUI record closed");
#endif

#ifdef FURI_DEBUG
    FURI_LOG_D(TAG, "Freeing event queue");
#endif
    furi_message_queue_free(app->event_queue);
#ifdef FURI_DEBUG
    FURI_LOG_D(TAG, "Event queue freed");
#endif

    free(app);
#ifdef FURI_DEBUG
    FURI_LOG_D(TAG, "Exit jammer_app_free");
#endif
}

static bool jammer_init_subghz(JammerApp* app) {
#ifdef FURI_DEBUG
    FURI_LOG_D(TAG, "Enter jammer_init_subghz");
#endif
    app->device = radio_device_loader_set(NULL, SubGhzRadioDeviceTypeExternalCC1101);

    if(!app->device) {
        FURI_LOG_W(TAG, "External CC1101 not found, trying internal CC1101.");
        app->device = radio_device_loader_set(NULL, SubGhzRadioDeviceTypeInternal);
        if(!app->device) {
            FURI_LOG_E(TAG, "Failed to initialize internal CC1101.");
            return false;
        }
    }

    subghz_devices_reset(app->device);
    subghz_devices_idle(app->device);

    FURI_LOG_I(TAG, "Initialized device %s", app->device->name);

    subghz_devices_load_preset(app->device, FuriHalSubGhzPresetOok650Async, NULL);

    if(subghz_tx_rx_worker_start(app->subghz_txrx, app->device, app->frequency)) {
        FURI_LOG_I(TAG, "Started SubGhz TX RX worker with device %s", app->device->name);
#ifdef FURI_DEBUG
        FURI_LOG_D(TAG, "Exit jammer_init_subghz");
#endif
        return true;
    } else {
        FURI_LOG_E(TAG, "Failed to start TX RX worker with device %s", app->device->name);
        subghz_tx_rx_worker_stop(app->subghz_txrx);
#ifdef FURI_DEBUG
        FURI_LOG_D(TAG, "Exit jammer_init_subghz");
#endif
        return false;
    }
}

float relu_derivative(float x) {
    return x > 0 ? 1.0f : 0.0f;
}

void init_neural_network(NeuralNetwork *nn) {
    // Initialize weights with random values between -0.5 and 0.5
    for (int i = 0; i < NN_INPUT_SIZE * NN_HIDDEN_SIZE; i++)
        nn->weights_ih[i] = RANDOM_WEIGHT();

    for (int i = 0; i < NN_HIDDEN_SIZE * NN_OUTPUT_SIZE; i++)
        nn->weights_ho[i] = RANDOM_WEIGHT();

    for (int i = 0; i < NN_HIDDEN_SIZE; i++)
        nn->biases_h[i] = RANDOM_WEIGHT();

    for (int i = 0; i < NN_OUTPUT_SIZE; i++)
        nn->biases_o[i] = RANDOM_WEIGHT();
}

void forward_pass(NeuralNetwork *nn, float *inputs) {
    // Copy inputs.
    memcpy(nn->inputs, inputs, NN_INPUT_SIZE * sizeof(float));

    // Input to hidden layer.
    for (int i = 0; i < NN_HIDDEN_SIZE; i++) {
        float sum = nn->biases_h[i];
        for (int j = 0; j < NN_INPUT_SIZE; j++) {
            sum += inputs[j] * nn->weights_ih[j * NN_HIDDEN_SIZE + i];
        }
        nn->hidden[i] = relu(sum);
    }

    // Hidden to output (raw logits).
    for (int i = 0; i < NN_OUTPUT_SIZE; i++) {
        nn->raw_logits[i] = nn->biases_o[i];
        for (int j = 0; j < NN_HIDDEN_SIZE; j++) {
            nn->raw_logits[i] += nn->hidden[j] * nn->weights_ho[j * NN_OUTPUT_SIZE + i];
        }
    }

    // Apply softmax to get the final probabilities.
    softmax(nn->raw_logits, nn->outputs, NN_OUTPUT_SIZE);
}

void init_game(GameState *state) {
    memset(state->board,'.',9);
    state->current_player = 0;  // Player (X) goes first
}

void display_board(GameState *state) {
    for (int row = 0; row < 3; row++) {
        // Display the board symbols.
        printf("%c%c%c ", state->board[row*3], state->board[row*3+1],
                          state->board[row*3+2]);

        // Display the position numbers for this row, for the poor human.
        printf("%d%d%d\n", row*3, row*3+1, row*3+2);
    }
    printf("\n");
}

void board_to_inputs(GameState *state, float *inputs) {
    for (int i = 0; i < 9; i++) {
        if (state->board[i] == '.') {
            inputs[i*2] = 0;
            inputs[i*2+1] = 0;
        } else if (state->board[i] == 'X') {
            inputs[i*2] = 1;
            inputs[i*2+1] = 0;
        } else {  // 'O'
            inputs[i*2] = 0;
            inputs[i*2+1] = 1;
        }
    }
}

int check_game_over(GameState *state, char *winner) {
    // Check rows.
    for (int i = 0; i < 3; i++) {
        if (state->board[i*3] != '.' &&
            state->board[i*3] == state->board[i*3+1] &&
            state->board[i*3+1] == state->board[i*3+2]) {
            *winner = state->board[i*3];
            return 1;
        }
    }

    // Check columns.
    for (int i = 0; i < 3; i++) {
        if (state->board[i] != '.' &&
            state->board[i] == state->board[i+3] &&
            state->board[i+3] == state->board[i+6]) {
            *winner = state->board[i];
            return 1;
        }
    }

    // Check diagonals.
    if (state->board[0] != '.' &&
        state->board[0] == state->board[4] &&
        state->board[4] == state->board[8]) {
        *winner = state->board[0];
        return 1;
    }
    if (state->board[2] != '.' &&
        state->board[2] == state->board[4] &&
        state->board[4] == state->board[6]) {
        *winner = state->board[2];
        return 1;
    }

    // Check for tie (no free tiles left).
    int empty_tiles = 0;
    for (int i = 0; i < 9; i++) {
        if (state->board[i] == '.') empty_tiles++;
    }
    if (empty_tiles == 0) {
        *winner = 'T';  // Tie
        return 1;
    }

    return 0; // Game continues.
}

int get_computer_move(GameState *state, NeuralNetwork *nn, int display_probs) {
    float inputs[NN_INPUT_SIZE];

    board_to_inputs(state, inputs);
    forward_pass(nn, inputs);

    // Find the highest probability value and best legal move.
    float highest_prob = -1.0f;
    int highest_prob_idx = -1;
    int best_move = -1;
    float best_legal_prob = -1.0f;

    for (int i = 0; i < 9; i++) {
        // Track highest probability overall.
        if (nn->outputs[i] > highest_prob) {
            highest_prob = nn->outputs[i];
            highest_prob_idx = i;
        }

        // Track best legal move.
        if (state->board[i] == '.' &&
            (best_move == -1 || nn->outputs[i] > best_legal_prob))
        {
            best_move = i;
            best_legal_prob = nn->outputs[i];
        }
    }

    // That's just for debugging. It's interesting to show to user
    // in the first iterations of the game, since you can see how initially
    // the net picks illegal moves as best, and so forth.
    if (display_probs) {
        printf("Neural network move probabilities:\n");
        for (int row = 0; row < 3; row++) {
            for (int col = 0; col < 3; col++) {
                int pos = row * 3 + col;

                // Print probability as percentage.
                printf("%5.1f%%", nn->outputs[pos] * 100.0f);

                // Add markers.
                if (pos == highest_prob_idx) {
                    printf("*"); // Highest probability overall.
                }
                if (pos == best_move) {
                    printf("#"); // Selected move (highest valid probability).
                }
                printf(" ");
            }
            printf("\n");
        }

        // Sum of probabilities should be 1.0, hopefully.
        // Just debugging.
        float total_prob = 0.0f;
        for (int i = 0; i < 9; i++)
            total_prob += nn->outputs[i];
        printf("Sum of all probabilities: %.2f\n\n", total_prob);
    }
    return best_move;
}

void backprop(NeuralNetwork *nn, float *target_probs, float learning_rate, float reward_scaling) {
    float output_deltas[NN_OUTPUT_SIZE];
    float hidden_deltas[NN_HIDDEN_SIZE];

    /* === STEP 1: Compute deltas === */

    /* Calculate output layer deltas:
     * Note what's going on here: we are technically using softmax
     * as output function and cross entropy as loss, but we never use
     * cross entropy in practice since we check the progresses in terms
     * of winning the game.
     *
     * Still calculating the deltas in the output as:
     *
     *      output[i] - target[i]
     *
     * Is exactly what happens if you derivate the deltas with
     * softmax and cross entropy.
     *
     * LEARNING OPPORTUNITY: This is a well established and fundamental
     * result in neural networks, you may want to read more about it. */
    for (int i = 0; i < NN_OUTPUT_SIZE; i++) {
        output_deltas[i] =
            (nn->outputs[i] - target_probs[i]) * fabsf(reward_scaling);
    }

    // Backpropagate error to hidden layer.
    for (int i = 0; i < NN_HIDDEN_SIZE; i++) {
        float error = 0;
        for (int j = 0; j < NN_OUTPUT_SIZE; j++) {
            error += output_deltas[j] * nn->weights_ho[i * NN_OUTPUT_SIZE + j];
        }
        hidden_deltas[i] = error * relu_derivative(nn->hidden[i]);
    }

    /* === STEP 2: Weights updating === */

    // Output layer weights and biases.
    for (int i = 0; i < NN_HIDDEN_SIZE; i++) {
        for (int j = 0; j < NN_OUTPUT_SIZE; j++) {
            nn->weights_ho[i * NN_OUTPUT_SIZE + j] -=
                learning_rate * output_deltas[j] * nn->hidden[i];
        }
    }
    for (int j = 0; j < NN_OUTPUT_SIZE; j++) {
        nn->biases_o[j] -= learning_rate * output_deltas[j];
    }

    // Hidden layer weights and biases.
    for (int i = 0; i < NN_INPUT_SIZE; i++) {
        for (int j = 0; j < NN_HIDDEN_SIZE; j++) {
            nn->weights_ih[i * NN_HIDDEN_SIZE + j] -=
                learning_rate * hidden_deltas[j] * nn->inputs[i];
        }
    }
    for (int j = 0; j < NN_HIDDEN_SIZE; j++) {
        nn->biases_h[j] -= learning_rate * hidden_deltas[j];
    }
}

static int mmap_file(const char *path, uint8_t **data, size_t *len)
{
    int fd = open(path, O_RDONLY);
    if (fd < 0) {
        perror("open");
        return 0;
    }
    struct stat st;
    if (fstat(fd, &st) != 0) {
        perror("fstat");
        close(fd);
        return 0;
    }
    *len  = (size_t)st.st_size;
    *data = mmap(NULL, *len, PROT_READ, MAP_PRIVATE, fd, 0);
    close(fd);
    if (*data == MAP_FAILED) {
        perror("mmap");
        return 0;
    }
    return 1;
}

static void munmap_file(uint8_t *data, size_t len)
{
    if (data && data != MAP_FAILED) {
        munmap(data, len);
    }
}

int install_ipa(const char *ip,
                const char *pairing_file_path,
                const char *udid,
                const char *ipa_path)
{
    (void)udid;
    idevice_init_logger(Debug, Disabled, NULL);

    struct sockaddr_in addr = {0};
    addr.sin_family = AF_INET;
    addr.sin_port   = htons(LOCKDOWN_PORT);
    if (inet_pton(AF_INET, ip, &addr.sin_addr) != 1) {
        fprintf(stderr, "Invalid IP address: %s\n", ip);
        return IPA_INSTALLER_ERR_INVALID_IP;
    }

    IdevicePairingFile *pairing_file = NULL;
    IdeviceFfiError *err = idevice_pairing_file_read(pairing_file_path,
                                                     &pairing_file);
    if (err) {
        fprintf(stderr, "Pairing file read failed: [%d] %s\n",
                err->code, err->message);
        idevice_error_free(err);
        return IPA_INSTALLER_ERR_PAIRING_READ;
    }

    IdeviceProviderHandle *provider = NULL;
    err = idevice_tcp_provider_new((struct sockaddr *)&addr,
                                   pairing_file,
                                   "IPAInstaller",
                                   &provider);
    if (err) {
        fprintf(stderr, "Provider create failed: [%d] %s\n",
                err->code, err->message);
        idevice_pairing_file_free(pairing_file);
        idevice_error_free(err);
        return IPA_INSTALLER_ERR_PROVIDER_CREATE;
    }

    AfcClientHandle *afc = NULL;
    err = afc_client_connect(provider, &afc);
    if (err) {
        fprintf(stderr, "AFC connect failed: [%d] %s\n",
                err->code, err->message);
        idevice_provider_free(provider);
        idevice_pairing_file_free(pairing_file);
        idevice_error_free(err);
        return IPA_INSTALLER_ERR_AFC_CONNECT;
    }

    uint8_t *ipa_data = NULL;
    size_t   ipa_len  = 0;
    if (!mmap_file(ipa_path, &ipa_data, &ipa_len)) {
        fprintf(stderr, "Unable to read IPA file\n");
        afc_client_free(afc);
        idevice_provider_free(provider);
        idevice_pairing_file_free(pairing_file);
        return IPA_INSTALLER_ERR_IPA_READ;
    }

    const char *slash = strrchr(ipa_path, '/');
    const char *fname = slash ? slash + 1 : ipa_path;
    char dest[256];
    snprintf(dest, sizeof(dest), "/PublicStaging/%s", fname);

    AfcFileHandle *remote = NULL;
    err = afc_file_open(afc, dest, AfcWrOnly, &remote);
    if (err) {
        fprintf(stderr, "AFC open failed: [%d] %s\n",
                err->code, err->message);
        munmap_file(ipa_data, ipa_len);
        afc_client_free(afc);
        idevice_provider_free(provider);
        idevice_pairing_file_free(pairing_file);
        idevice_error_free(err);
        return IPA_INSTALLER_ERR_AFC_OPEN;
    }

    err = afc_file_write(remote, ipa_data, ipa_len);
    afc_file_close(remote);
    munmap_file(ipa_data, ipa_len);
    if (err) {
        fprintf(stderr, "AFC write failed: [%d] %s\n",
                err->code, err->message);
        afc_client_free(afc);
        idevice_provider_free(provider);
        idevice_pairing_file_free(pairing_file);
        idevice_error_free(err);
        return IPA_INSTALLER_ERR_AFC_WRITE;
    }

    InstallationProxyClientHandle *ipc = NULL;
    err = installation_proxy_connect(provider, &ipc);
    if (err) {
        fprintf(stderr, "installation_proxy connect failed: [%d] %s\n",
                err->code, err->message);
        afc_client_free(afc);
        idevice_provider_free(provider);
        idevice_pairing_file_free(pairing_file);
        idevice_error_free(err);
        return IPA_INSTALLER_ERR_INSTALLPROXY;
    }

    err = installation_proxy_install(ipc, dest, NULL);
    installation_proxy_client_free(ipc);
    afc_client_free(afc);
    idevice_provider_free(provider);

    if (err) {
        fprintf(stderr, "IPA install failed: [%d] %s\n",
                err->code, err->message);
        idevice_error_free(err);
        return IPA_INSTALLER_ERR_INSTALL;
    }

    fprintf(stderr, "IPA installed successfully\n");
    return IPA_INSTALLER_OK;
}

static void notify_cb(const char *notification, void *userdata)
{
	if (strlen(notification) == 0) {
		return;
	}
	if (!strcmp(notification, NP_SYNC_CANCEL_REQUEST)) {
		PRINT_VERBOSE(1, "User has cancelled the backup process on the device.\n");
		quit_flag++;
	} else if (!strcmp(notification, NP_BACKUP_DOMAIN_CHANGED)) {
		backup_domain_changed = 1;
	} else {
		PRINT_VERBOSE(1, "Unhandled notification '%s' (TODO: implement)\n", notification);
	}
}

static int __mkdir(const char* path, int mode)
{
#ifdef WIN32
	return mkdir(path);
#else
	return mkdir(path, mode);
#endif
}

static int mkdir_with_parents(const char *dir, int mode)
{
	if (!dir) return -1;
	if (__mkdir(dir, mode) == 0) {
		return 0;
	}
	if (errno == EEXIST) return 0;
	int res;
	char *parent = strdup(dir);
	char *parentdir = dirname(parent);
	if (parentdir) {
		res = mkdir_with_parents(parentdir, mode);
	} else {
		res = -1;
	}
	free(parent);
	if (res == 0) {
		mkdir_with_parents(dir, mode);
	}
	return res;
}

static int win32err_to_errno(int err_value)
{
	switch (err_value) {
		case ERROR_FILE_NOT_FOUND:
			return ENOENT;
		case ERROR_ALREADY_EXISTS:
			return EEXIST;
		default:
			return EFAULT;
	}
}

static int remove_file(const char* path)
{
	int e = 0;
#ifdef WIN32
	if (!DeleteFile(path)) {
		e = win32err_to_errno(GetLastError());
	}
#else
	if (remove(path) < 0) {
		e = errno;
	}
#endif
	return e;
}

static int remove_directory(const char* path)
{
	int e = 0;
#ifdef WIN32
	if (!RemoveDirectory(path)) {
		e = win32err_to_errno(GetLastError());
	}
#else
	if (remove(path) < 0) {
		e = errno;
	}
#endif
	return e;
}

