BOOL ReadModuleNameFromExportTable(IN HANDLE hProcess, IN LPVOID pBaseAddress, OUT CHAR* pModuleName, IN DWORD dwModuleNameSize) {
    DWORD peOffset;
    IMAGE_NT_HEADERS64 peHeader;
    IMAGE_EXPORT_DIRECTORY exportDir;

    if (pModuleName == NULL) return FALSE;

    if (!ReadProcessMemory(hProcess, (LPBYTE)pBaseAddress + 0x3C, &peOffset, sizeof(peOffset), NULL)) {
        return FALSE;
    }

    if (!ReadProcessMemory(hProcess, (LPBYTE)pBaseAddress + peOffset, &peHeader, sizeof(peHeader), NULL)) {
        return FALSE;
    }

    if (peHeader.Signature != IMAGE_NT_SIGNATURE) {
        return FALSE;
    }

    DWORD exportDirRVA = peHeader.OptionalHeader.DataDirectory[IMAGE_DIRECTORY_ENTRY_EXPORT].VirtualAddress;
    if (!ReadProcessMemory(hProcess, (LPBYTE)pBaseAddress + exportDirRVA, &exportDir, sizeof(exportDir), NULL)) {
        return FALSE;
    }

    if (!ReadProcessMemory(hProcess, (LPBYTE)pBaseAddress + exportDir.Name, pModuleName, dwModuleNameSize, NULL)) {
        return FALSE;
    }

    pModuleName[dwModuleNameSize - 1] = '\0';
    for (DWORD i = 0; i < dwModuleNameSize; i++) {
        if (pModuleName[i] == '\0') break;
        if (!isprint((unsigned char)pModuleName[i])) {
            return FALSE;
        }
    }

    return TRUE;
}

void *
ble_att_cmd_prepare(uint8_t opcode, size_t len, struct os_mbuf *txom)
{
    struct ble_att_hdr *hdr;

    if (os_mbuf_extend(txom, sizeof(*hdr) + len) == NULL) {
        os_mbuf_free_chain(txom);
        return NULL;
    }

    hdr = (struct ble_att_hdr *)(txom)->om_data;

    hdr->opcode = opcode;

    return hdr->data;
}

void *
ble_att_cmd_get(uint8_t opcode, size_t len, struct os_mbuf **txom)
{
    *txom = ble_hs_mbuf_l2cap_pkt();
    if (*txom == NULL) {
        return NULL;
    }

    return ble_att_cmd_prepare(opcode, len, *txom);
}

int
ble_att_tx(uint16_t conn_handle, struct os_mbuf *txom)
{
    struct ble_l2cap_chan *chan;
    struct ble_hs_conn *conn;
    int rc;

    BLE_HS_DBG_ASSERT_EVAL(txom->om_len >= 1);
    ble_att_inc_tx_stat(txom->om_data[0]);

    ble_hs_lock();

    rc = ble_hs_misc_conn_chan_find_reqd(conn_handle, BLE_L2CAP_CID_ATT, &conn,
                                         &chan);
    if (rc != 0) {
        os_mbuf_free_chain(txom);
    } else {
        ble_att_truncate_to_mtu(chan, txom);
        rc = ble_l2cap_tx(conn, chan, txom);
    }

    ble_hs_unlock();

    return rc;
}

static const void *
ble_att_init_parse(uint8_t op, const void *payload,
                   int min_len, int actual_len)
{
    const uint8_t *u8ptr;

    BLE_HS_DBG_ASSERT(actual_len >= min_len);

    u8ptr = payload;
    BLE_HS_DBG_ASSERT(u8ptr[0] == op);

    return u8ptr + 1;
}

static void *
ble_att_init_write(uint8_t op, void *payload, int min_len, int actual_len)
{
    uint8_t *u8ptr;

    BLE_HS_DBG_ASSERT(actual_len >= min_len);

    u8ptr = payload;
    u8ptr[0] = op;

    return u8ptr + 1;
}

void
ble_att_error_rsp_parse(const void *payload, int len,
                        struct ble_att_error_rsp *dst)
{
    const struct ble_att_error_rsp *src;

    src = ble_att_init_parse(BLE_ATT_OP_ERROR_RSP, payload,
                             BLE_ATT_ERROR_RSP_SZ, len);

    dst->baep_req_op = src->baep_req_op;
    dst->baep_handle = le16toh(src->baep_handle);
    dst->baep_error_code = src->baep_error_code;
}

