int _GetDpiForWindow(HWND hwnd) {
    HMODULE hUser32 = GetModuleHandle("user32.dll");
    if (hUser32) {
        _GetDpiForWindowFunc _getDpiForWindow = (_GetDpiForWindowFunc)GetProcAddress(hUser32, "GetDpiForWindow");
        if (_getDpiForWindow) {
            return _getDpiForWindow(hwnd);
        }
    }
    return 96;
}

