    POINT pt;
    GetCursorPos(&pt);

    HMENU hMenu = CreatePopupMenu();
    AppendMenu(hMenu, MF_STRING, ID_TRAY_SHOW, "Show");
    AppendMenu(hMenu, MF_STRING, ID_TRAY_HIDE, "Hide");
